quests[12152] = { id = 12152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'arraks Ende", description = "Es ist gut, Euch wieder unter den Lebenden begrüßen zu dürfen. Viele von denen, die auf dem Weg der Toten wandeln, kehren nicht zurück, um davon zu berichten.\n\nWährend Ihr weg wart, hatte Kraz eine Vision, die ihm offenbarte, was noch zu tun ist.\n\nIn der Gruft liegt noch irgendwo eine heilige Opfergabe. Nehmt diesen Seelenstaub, der aus den von Euch gesammelten Überresten gewonnen wurde und benutzt ihn auf der Opfergabe.\n\nDie mit dem Staub bedeckte Opfergabe wird dem verderbten Kriegsherren ein Ende bereiten und viele gepeinigte Seelen erlösen.\n\nMögen Euch die Geister Euch in Euren Handlungen leiten, {name}.", sourceObjective = "Kraz in Harkors Lager möchte, dass Ihr die heilige Drakkariopfergabe aus den Ruinen von Drakil'jin holt und den Drakkariseelenstaub darauf benutzt. Benutzt die beseelte Drakkariopfergabe bei den Gongs außerhalb der Ruinen von Drakil'jin.", completion = "Es ist vollbracht.\n\nEure Selbstlosigkeit hat vielen Seelen ewigen Frieden gebracht und Äonen der Qual beendet.\n\nMöge diese Tat Eure eigene Seele erleuchten und die Bürden, die Ihr tragt, leichter machen, denn ich sehe, dass Ihr noch viele Gefahren bestehen müsst.\n\nLebt wohl, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12153] = { id = 12153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eisenthan und sein Amboss", description = "Nun, da Ihr Euren Kriegsgolem aufgeladen habt, werden wir all diese Energie einer guten Sache zuführen. Aktiviert den Golem innerhalb von Dun Argol, um ihn zu kontrollieren.\n\nWir haben Informationen, dass Dun Argols Anführer, Eisenthan Zornhammer, von seinem Leibwächter rund um die Uhr beschützt wird.\n\nDieser Leibwächter ist das Konstrukt, mit dem er reist. Er wird der Amboss genannt. Setzt das Konstrukt außer Gefecht und sein Schutz wird vernichtet.\n\nDer Than befindet sich in dem Gebäude an der obersten Stelle Dun Argols und überwacht vom untersten Geschoss aus die Produktion.", sourceObjective = "Setzt die Fähigkeiten Eures Kriegsgolems ein, besiegt den Eisenthan Zornhammer und kehrt dann zu Raegar Brechbraue im Prospektorat zurück.", completion = "Es hat funktioniert?\n\n<Raegar räuspert sich.>\n\nIch meine… Natürlich hat es funktioniert! Das ist unglaublich!\n\nIn Zukunft werden Initianden der Forscherliga die Geschichte hören, wie Raegar Brechbraue, {name} und ein Blechkasten von einem Golem den Than von Dun Argol besiegten!", sourceObjectiveStatus = "unverified-source-field" }
quests[12154] = { id = 12154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stromausfall", description = "In der großen Halle an der Spitze von Dun Argol befindet sich die Energieversorgung für das ganze Gebiet. Wenn Ihr den Kraftkern zerstören könnt, wird es Dun Argol für einige Zeit lahm legen.\n\nKeine Energie bedeutet keine Golems, keine Wachposten und keine Blitzwaffen mehr.\n\nAls wir hier heraufgeschickt wurden, sagte man uns, dieser Sprengstoff sei für Ausgrabungen gedacht, aber dank Eisenthan Zornhammer musste die Forschung ja eingestellt werden. Wir können ihn vielleicht dennoch verwenden - er ist das einzig verfügbare Mittel, mit dem wir den Kraftkern zerstören können.", sourceObjective = "Benutzt Raegars Sprengstoff, um den Runenkraftkern in Dun Argol zu zerstören, und erstattet anschließen Bericht bei Raegar Brechbraue im Prospektorat.", completion = "<Raegar nickt anerkennend.>\n\nIch kann's nicht mit ansehen, wie Sprengstoff auf den Müll wandert, und so erteilt er unseren Feinden sicher einen herben Rückschlag.", sourceObjectiveStatus = "unverified-source-field" }
quests[12155] = { id = 12155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zermatsch den Kürbis", description = "Diese große Kürbislaterne befindet sich im Zentrum des Dorfes. Ihre Augen betrachten jeden, der sie ansieht, und verraten, dass eine dunkle Bedrohung dahinter lauert.\n\nWenn man den Kürbis zermatscht, wird ein altes, versengtes, heiliges Symbol offenbart.", sourceObjective = "Bring das versengte, heilige Symbol zur maskierten Waisenmatrone.", progress = "Ja, {name}?", completion = "Ihr habt das in der Kürbislampe des kopflosen Reiters gefunden? Es ist ein altes Symbol des Lichts. Es muss einst dem Reiter gehört haben, bevor er verflucht und zu dem Monster wurde, das er heute ist. Habt Dank, {name}. Dieses Symbol gehört in Paladinhände. Ich werde sicherstellen, dass sie es erhalten.\n\nOh, und das hätte ich fast vergessen! Ihr habt einen stillen Bewunderer...\n\nEines der Kinder wollte, dass Ihr dies erhaltet. Sie war zu schüchtern, es Euch selbst zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12156] = { id = 12156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ABGELEHNT", description = "Ich hätte eigentlich vor ungefähr einer Stunde in Richtung Nordwesten, nach Silberwasser, aufbrechen sollen. Meine Militäreskorte scheint sich zu verspäten.\n\nIch werde nicht zulassen, dass diese diplomatische Mission in Verzug gerät, nur weil ein neuer Rekrut verschlafen hat.\n\nWir verhandeln gerade ein Abkommen mit den Einheimischen und Pünktlichkeit ist von größter Bedeutung. Was meint Ihr? Wenn Ihr mich begleitet, so werdet Ihr fürstlich entlohnt werden für Eure Mühen.", sourceObjective = "Eskortiert den Gesandten der Allianz ins Dorf Silberwasser. Erstattet Leutnant Dumont bei der Ammertannhütte Bericht, sobald Ihr Eure Aufgabe abgeschlossen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12157] = { id = 12157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Kurier", description = "Wir können uns glücklich schätzen, es bis hierher geschafft zu haben, {name}. Wir wurden von der Geißel aus dem Hinterhalt angegriffen, als wir anlandeten.\n\nWie sich herausstellte, war einer meiner Männer ein Spion des Kults der Verdammten. Thassarian scheint mehr Beweise über die Infiltration durch die Kultisten zu haben. So wie es aussieht, zieht sich das Ganze bis in die Spitze.\n\nIch habe einen meiner besten Kuriere auf den Weg zu unserem Außenposten in der westlichen Drachenöde geschickt, doch er ist noch nicht zurückgekehrt. Werdet Ihr in die Drachenöde reisen und nach ihm suchen? Kurier Lanson ist sein Name.", sourceObjective = "Sprecht mit Kurier Lanson in Sternenruh in der Drachenöde.", completion = "Als ich die Brücke überquerte, die in die Drachenöde führte, wurde ich aus dem Hinterhalt von einer Gruppe Anub'ar angegriffen! Ich war umzingelt! Diese Scheusale wussten, dass ich kommen würde. Ich konnte gerade noch meine Haut retten. Diese Liste, die ich in Händen halte, muss nach Wintergarde gebracht werden, doch meine Wunden sind zu schwer, als dass ich die Reise schaffen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12158] = { id = 12158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohlsteinmine", description = "Ich wollte eigentlich ein paar unserer Jungs losschicken, um nach der Hohlsteinmine zu sehen. Hatten aber noch keine Gelegenheit - alle Hände voll zu tun mit der Horde im Westen und den Eisenzwergen im Osten.\n\nWenn allerdings Dumont Euch gesandt hat, kann ich Euch wenigstens in die richtige Richtung schicken.\n\nIhr findet den Eingang zur Mine nicht weit von hier im Nordwesten. Versucht einzuschätzen, ob es sich lohnt, dort zu operieren. Wir könnten die zusätzlichen Ressourcen gut gebrauchen, solange unsere Mine in Fernhain geschlossen ist.", sourceObjective = "Sucht nach Hinweisen in der Hohlsteinmine, nordwestlich vom Lager der Westfallbrigade.", completion = "Ihr seid gekommen, um mir zu helfen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[12159] = { id = 12159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenunfrieden", description = "<Petrov wirkt zutiefst verstört, atmet schwer und lässt seinen Blick nervös über die Mine schweifen.>\n\nMeine Kameraden... wir müssen ihren Seelen Frieden gewähren! Ich töte sie und töte sie, aber... sie kommen einfach zurück!\n\nErst hatte ich ja eine Idee, aber ich denke nicht, dass ich den Mut habe, sie selbst auszuführen.\n\nVielleicht könnt Ihr das für mich tun? Nehmt diese Laterne und verbrennt mit ihrem Öl die Leichen, damit sie nicht wieder aufstehen.\n\nIch beantworte Eure Fragen später. Helft erst meinen Freunden!", sourceObjective = "Petrov bei der Hohlsteinmine möchte, dass Ihr mit der Minenarbeiterlaterne die Leichen von 8 Minenarbeitern der Hohlsteinmine verbrennt.", completion = "Ruhet in Frieden, Freunde! Seid unbesorgt - ich erzähle allen, dass wir niemals aufgegeben haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[12160] = { id = 12160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Name aus der Vergangenheit", description = "Es hat funktioniert! Es hat funktioniert! Meine Kameraden können endlich ihre wohlverdiente Ruhe genießen. Wir, die Bergleute von der Hohlsteinmine, bringen immer unsere Arbeit zu Ende - wir geben niemals auf!\n\nAus diesem Grund hat Arugal an uns auch ein Exempel statuiert. Wir wollten uns nicht fügen, müsst Ihr wissen. Wir wollten uns nicht seinem Wolfskult anschließen!", sourceObjective = "Kehrt zu Hauptmann Gryan Starkmantel im Lager der Westfallbrigade zurück.", completion = "Verflucht soll unser Glück sein. Wir finden die einzige Mine auf dieser Seite der Hügel, die noch intakt ist, und sie ist voller Diener der Geißel.\n\nNichts für ungut, mein Freund. Doch es hört sich so an, als sei der Überlebende, den Ihr gefunden habt, durch den Verlust seiner Freunde ein wenig verstört. Arugal ist schon seit Jahren tot... Ich habe einst sogar sein Grab gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12161] = { id = 12161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuna die Blinde", description = "He, Ihr. Ich habe zufällig gehört, was Ihr da dem Hauptmann erzählt habt, und wollte Euch nur sagen… Die Dinge sind nicht ganz so einfach in Nordend.\n\nNur weil jemand tot ist, heißt das nicht, dass er ganz verschwindet.\n\nSüdwestlich von hier, in der Nähe des Vordrassilpasses, lebt eine blinde Frau, die unter dem Namen Ruuna die Blinde bekannt ist. Man sagt, dass sie mit den Toten spricht und Visionen von der Vergangenheit und der Zukunft hat.\n\nIch habe nicht alles von Eurer Geschichte mitbekommen, aber es hört sich an, als könnte sie für Euch von Interesse sein.", sourceObjective = "Sprecht mit Ruuna der Blinden in Ruunas Lager in der Nähe des Vordrassilpasses.", completion = "Euch verlangt es nach Wissen, das Ihr nicht selbst erlangen könnt, deswegen seid Ihr zu mir gekommen. Doch muss ich Euch warnen, Fremder, womöglich wird es Euch nicht gefallen, was ich zu sagen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[12162] = { id = 12162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Julheim" }
quests[12163] = { id = 12163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Böse lauert am Meeresgrund" }
quests[12164] = { id = 12164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stunde des Worgen", description = "Es ist wohl Zeit, {name}. Arugal muss besiegt werden.\n\nNehmt ein paar Leute mit, denen Ihr vertrauen könnt, und geht zur Blutmondinsel gleich hier im Osten vor der Küste.\n\nWir werden schnell zuschlagen. Schaltet Arugals Leutnants aus - ich komme dann zu Euch, wenn es Zeit ist, das Monster höchstpersönlich zu erlegen.", sourceObjective = "Sasha im Handelsposten Weißkiefer möchte, dass Ihr zur Blutmondinsel geht und Selas, Varlam, Blutschlund und den Schatten von Arugal tötet.", completion = "Wir haben ihn gut erwischt, {name}. Doch nicht gut genug.\n\nEine Sache ist jedoch sicher... In dieser Gegend werden wir ihn nicht mehr zu Gesicht bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12165] = { id = 12165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein faszinierender Plan", description = "Ausgrabungsleiter Rokar hat sich entschieden, uns zu helfen. Er hat einen Plan erarbeitet, die Stärke der Eisenzwerge gegen sie zu wenden.\n\nIch muss zugeben, dass unser 'Freund' einsichtiger ist, als ich ihm zugetraut hätte. Er hat Recht, wenn er sagt, dass wir zu wenige sind, um einen direkten Angriff wagen zu können.\n\nReist nach Dun Argol, in die verschneiten Regionen im Südosten, und stehlt alle Blaupausenteile für ihre Kriegsgolems von den Runenschmieden dort. Bringt die vollständige Blaupause zu Rokar und wir werden sehen, ob sein Plan Wert hat.", sourceObjective = "Bringt die vollständige Blaupause für die Kriegsgolems zu Ausgrabungsleiter Rokar in Camp Oneqwah.", progress = "Habt… habt Ihr die Blaupausen, die ich brauche?", completion = "Also will Tormak den Plan in die Tat umsetzen? Ich vermute, er hätte Euch nicht geschickt, wenn er das nicht wollte.\n\nOh Mann… wie kriege ich bei all dem Druck nur heraus, wie das Ganze zusammengesetzt werden muss?", sourceObjectiveStatus = "unverified-source-field" }
quests[12166] = { id = 12166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das flüssige Feuer Elunes", description = "Werdet Ihr mir beistehen, {race}?\n\nDie Geißel ist weiter nach Norden vorgedrungen, nach Eisnebel. Wohin auch immer sie ziehen, sie verbreiten ihr Übel und alle Kreaturen leiden.\n\nNehmt diese Phiole, sie ist mit dem flüssigen Feuer Elunes aus dem Mondbrunnen gefüllt. Bitte, nutzt dieses Elixier und läutert die Kadaver der toten Wildtiere, die ihr findet.", sourceObjective = "Aufseherin Jodi Mondweise in Sternenruh hat Euch gebeten, das flüssige Feuer Elunes zu nutzen, um die Kadaver von 6 verseuchten Elchen und 6 tollwütigen Grizzlys zu läutern.", completion = "Wir haben für die Kreaturen dieses Landes getan, was möglich war. Jetzt müssen wir direkte Schritte gegen jene unternehmen, die das alles verursacht haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[12167] = { id = 12167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Kultisten", description = "Die Kultisten der Anub'ar sind indirekt für die Verseuchung der Tiere hier verantwortlich und wir müssen dem ein Ende setzen!\n\nDie Dämpfe, die aus den Anzügen der Kultisten quellen durchsickern alles, dem sie sich nähern, vergiften und verderben ihre Umgebung.\n\nIhr müsst nach Eisnebel im Norden gehen und sie töten. Bringt mir all die Anzüge, die Euren Angriff unbeschadet überstehen, und ich werde mich darum kümmern, dass diese fachgerecht entsorgt werden.", sourceObjective = "Sammelt für Aufseherin Jodi Mondweise 5 funktionstüchtige Kultistenanzüge und bringt sie zu ihr nach Sternenruh.", progress = "Diese Kultisten sind eine der Geißeln der Schöpfung!", completion = "Gut gemacht.\n\nIch werde diese widerwärtigen Kleider im Mondbrunnen waschen und sie mit der Macht der Mondgöttin vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[12168] = { id = 12168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zangus Ehrengabe", description = "Eine Inschrift auf der Rückseite der Ehrengabe gibt kund:\n\n\"Gewidmet meinem Lieblingsschüler,\n\nSolltest du weiterhin derart vielversprechende Talente zeigen, werde ich dich Wunder lehren, die deine kühnsten Träume übersteigen.\n\nSolltest du nicht, werde ich deine Entsorgung in Auftrag geben.\n\nMit den besten Wünschen,\n\nHochkultist Zangus\"\n\nOhne Zweifel wird die Aufseherin in Sternenruh die Ehrengabe sehen wollen.", sourceObjective = "Bringt Zangus Ehrengabe zu Aufseherin Jodi Mondweise in Sternenruh.", progress = "Etwas Verderbtes ist nah, ich spüre es.\n\nIhr tragt dieses Unheil mit Euch! Was ist es, {name}?", completion = "So, der Anführer der Kultisten hat sich also selbst entlarvt. Wir haben einen Namen.\n\nEitelkeit und Stolz werden sein Untergang sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[12169] = { id = 12169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochkultist", description = "Ich habe bereits von Zangus geträumt, doch ohne den Kontext, den Ihr mir hier liefert, wusste ich nicht, was es zu bedeuten hat. Ihr habt Klarheit in die Vision gebracht, mit der mich die Göttin segnete und ich weiß nun, dass wir ihn im Norden, in der Grube von Narjun finden werden.\n\nIhr kennt unser Ziel, {name}. Wenn wir dem Leiden des Landes ein Ende setzen wollen, muss der Hochkultist sterben!", sourceObjective = "Aufseherin Jodi Mondweise in Sternenruh hat Euch gebeten, Hochkultist Zangus zu töten.", completion = "Nun, da der Hochkultist vernichtet ist, kann der Rest seiner Streitkräfte von diesem Landstrich gefegt werden und die Tiere werden sich erholen.\n\nVielen Dank, {name}. Möge die Göttin Eure Pfade erhellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12170] = { id = 12170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keilerei in Schwarzwasser", description = "Kurz nachdem wir angekommen sind, hat die Venture Company ihren Betrieb eingestellt. Sie hatten ganz klar Angst davor, was wir mit Raffzähnen wie ihnen machen würden.\n\nNun da sie weg sind, sind ihre Holzfällerlager verlassen. Unsere Kriegsmaschinerie ist ein hungriges Biest... Ohne unsere Vorräte aufzustocken, werden wir es nicht zur Eiskrone schaffen.\n\nLeider scheint die Allianz denselben Gedanken zu haben und wir müssen sicherstellen, dass wir diejenigen sind, die obsiegen. Macht Euch auf den Weg zum Holzfällerlager und helft uns, den Allianzabschaum zu bekämpfen.", sourceObjective = "Räuberhauptmann Kronn möchte, dass Ihr 10 Einheiten oder Spieler der Allianz beim Holzfällerlager von Schwarzwasser tötet.", completion = "Gut gemacht, {name}. Wir haben zwar noch nicht die volle Kontrolle über das Holzfällerlager, aber dank Euch sind wir dem Ziel, die Allianzwürmer zu zertreten, einen Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12171] = { id = 12171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Verrätern und Verrat", description = "Die Liste, die in meinem Besitz ist, muss zu Hochkommandant Halford Wyrmbann gebracht werden. Er befehligt die 7. Legion, die in der Feste Wintergarde an der östlichen Grenze der Drachenöde.\n\nFalls einige der Verräter auf dieser Liste in Wintergarde stationiert sind... könnte das katastrophale Folgen haben.\n\nBeeilung, {name}. Zeigt Palena Silberwolke hier in Sternenruh das Dokument und erklärt ihr Eure Mission. Sie wird Euch auf ihrem schnellsten Hippogryphen zur Feste Wintergarde schicken!", sourceObjective = "Zeigt Palena Silberwolke in Sternenruh das Schreiben der Allianz.", progress = "Hallo, {race}.", completion = "<Palena liest die Notiz.>\n\nIhr werdet meinen schnellsten Hippogryph nehmen, {race}! Diese Informationen müssen unverzüglich Oberkommandant Wyrmbann übergeben werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12172] = { id = 12172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstimmung auf Dalaran", description = "Willkommen, <Magier/Magierin>.\n\nIhr müsst Euch mittlerweile schon gefragt haben, wo Dalaran ist und wie man dorthin kommt. Nun, ich werde Euch helfen.\n\nDoch bevor ich Euch beibringen kann, wie man sich zu unserer glorreichen Stadt hinteleportiert, müsst Ihr Euch auf Nordends Leylinien abstimmen - sonst würdet Ihr nämlich vernichtet werden.\n\nHier, nehmt diesen Abstimmungskristall und verwendet ihn in der Grube unter der Sognadel in den Mondruhgärten gen Westen; dann werdet Ihr bereit sein, den Zauberspruch zu lernen.", sourceObjective = "Das Abbild der Erzmagierin Modera in Sternenruh möchte, dass Ihr Euch auf Nordends Leylinien abstimmt.", completion = "Nun gut. Wenn Ihr bereit seid, dann bin ich es auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12173] = { id = 12173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstimmung auf Dalaran", description = "Grüße, <Magier/Magierin>.\n\nIhr müsst Euch mittlerweile schon gefragt haben, wo Dalaran ist und wie man dorthin kommt. Nun, ich kann Euch in der Sache helfen, wenn Ihr einen einfachen Test überstehen könnt.\n\nDoch bevor ich Euch beibringe, wie man sich zu unserer glorreichen Stadt teleportieren kann, müsst Ihr Euch auf Nordends Leylinien abstimmen - andernfalls würdet Ihr Euch nämlich selbst vernichten!\n\nHier, nehmt diesen Abstimmungskristall und verwendet ihn in der Grube unter der Sognadel in den Mondruhgärten gen Südwesten; dann werdet Ihr bereit sein, Euch meine Lehre anzueignen.", sourceObjective = "Das Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer möchte, dass Ihr Euch auf Nordends Leylinien abstimmt.", completion = "Also gut. Wenn Ihr denkt, dass Ihr bereit seid, dann lasst uns nicht viel mehr von meiner Zeit verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12174] = { id = 12174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochkommandant Halford Wyrmbann", description = "<Palena gibt Euch das Schreiben zurück.>\n\nSchneesturm wird Euch zur Feste Wintergarde bringen, {name}. Ich versichere Euch, dass das der schnellste Ritt wird, den Ihr je unternommen habt. Geht jetzt!", sourceObjective = "Überbringt Hochkommandant Halford Wyrmbann das Schreiben der Allianz. Er befindet sich in der Feste Wintergarde im Osten der Drachenöde.", progress = "Was habt Ihr da, Soldat?", completion = "<Der Oberkommandant liest das Schreiben durch und knüllt es dann zusammen.>\n\nWisst Ihr, wo die Leute auf dieser Liste jetzt sind? Seht mal nach draußen, neben dem Eingangstor. Sie hängen von den Bögen.\n\nGhulköder...", sourceObjectiveStatus = "unverified-source-field" }
quests[12175] = { id = 12175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graue Worgbälge", description = "Lass mich dir was sagen, Mann: Wenn du dafür verantwortlich bist, die Armeen der Horde auszurüsten, dann brauchst du 'ne Menge Bälge!\n\nEroberin Krenna, die Wölfin, die diesen Ort hier leitet, hat mir 'ne knappe Frist gesetzt. Wenn ich ihr gesamtes Regiment nicht bis Ende der Woche ausgerüstet hab', dann kann ich mit den Bären in der Grube spielen.\n\nHilf mir aus und ich zahle dir einen Spitzenpreis. Ich brauche Bälge von Graunebeljägern.\n\nDu findest sie in Gruppen überall im Norden, auf der Jagd nach Hirschen. Denk dran, Mann: Spitzenpreis!", sourceObjective = "Balghändler Jun'ik möchte, dass Ihr ihm 3 graue Worgbälge von Graunebeljägern in den nördlichen Wäldern bringt.", progress = "Hast du die Bälge, Mann?", completion = "Du hast mein Leben gerettet, Bruder. Falls du an mehr Arbeit interessiert bist: Es gibt noch mehr, wo das herkam.", sourceObjectiveStatus = "unverified-source-field" }
quests[12176] = { id = 12176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Ersatz", description = "Krenna wird Worgbälge für die ganzen Kleider brauchen. Für ihre Armee wird es jedoch nicht genug von den Bälgen geben - jetzt nicht und auch in Zukunft nicht.\n\nDiese Worgs - die sind dünn, Mann! Okay, ich sag dir, was wir machen... sofern du ein Geheimnis für dich behalten kannst.\n\nIm Osten von Voldrune gibt es Grizzlybären so fett wie Oger. Diese großen Bälge - die können wir benutzen!\n\nBeeil dich, <Bruder/Schwester>. Krenna ist nicht gerade für ihre Geduld bekannt.", sourceObjective = "Balghändler Jun'ik möchte, dass Ihr ihm 6 Grizzlybälge bringt.", progress = "Hast du die Bälge dabei, Mann?", completion = "Ich steh' in deiner Schuld, Mann. Nimm dies als Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12177] = { id = 12177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jun'iks Vertuschung", description = "Ah, wir ham ein kleines Problem. Grizzlyfelle... sin' braun, Mann!\n\nDenk nach... Denk nach!\n\nIch hab's, Mann! Es is' doch so: Grau is' schwarz und weiß durcheinander vermischt. Du besorgst mir ein bisch'n Kohle und ein bisch'n Mehl, ich werd' das alles mahlen und bestäub' die Felle damit. Das wird keinem auffallen!\n\nKohle gibt's in der Schmiede zum Verhütten und Mehl krichst du beim Versorger.", sourceObjective = "Bringt dem Balghändler Jun'ik in der Burg Siegeswall in den Grizzlyhügeln 1 Kohlestück und 5 Portionen herkömmliches Mehl.", progress = "Hast du den Kram, Mann?", completion = "Hoffen wir das Beste, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12178] = { id = 12178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Krenna", description = "Das is' es, Mann. Lass uns diese Felle zu Krenna bringen und gucken, ob sie den Test besteh'n.\n\nHoffen wir, dass Krenna nix bemerkt, um unserer beider willen.", sourceObjective = "Nehmt das Bündel Felle und bringt es zu Krenna in Burg Siegeswall.", progress = "Habt Ihr eigentlich irgendeine Ahnung, mit wem Ihr sprecht?", completion = "Für wen haltet Ihr mich eigentlich? Diese Felle riechen nach Mehl!\n\nDies ist eine echte Beleidigung der Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[12180] = { id = 12180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangenen Ausgrabungsleiter", description = "Raegar hat ein Team von Ausgrabungsleitern nach Dun Argol gesandt, um nach Artefakten und Informationen über die Geschichte der Siedlung zu suchen. Raegars Team hätte nie gedacht, dass so viele Feinde dort sein würden.\n\nSie werden gefangen gehalten, während die Eisenzwerge zum Krieg rüsten. Wir haben nicht genug Männer, um sie da herauszuboxen, und Raegar ist so sehr in seine Phantasien zur Vernichtung der Eisenzwerge versunken, dass er keine große Hilfe wäre.\n\nSomit liegt es an Euch, {name}. Jeder der Eisen oder ihrer Diener könnte den Schlüssel zu den Zellen, in denen unsere Männer gefangen gehalten werden, bei sich tragen.", sourceObjective = "Befreit die Ausgrabungsleiter Gann, Torgan und Varana, dann kehrt zu Gebirgsjäger Kilian im Prospektorat zurück.", completion = "<Gebirgsjäger Kilian hört Euch zu, als Ihr erzählt, was die entführten Ausgrabungsleiter zu berichten hatten.>\n\nSie erwähnten Loken und einen Krieg gegen Steinriesen? Seid Ihr sicher?\n\nAlso waren Raegars Instinkte richtig. wir müssen einen Weg dort hinein finden und mehr über ihre Pläne herausbekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12181] = { id = 12181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt dem Zeugs einen Namen", description = "Du meine Güte, wie lange ist es her? Wie lange arbeiten wir nun schon an dieser verdammten Seuche? Wir haben eine halbe Ewigkeit mit Fehlschlägen verbracht und wurden nun endlich mit Perfektion gesegnet. Dieses Zeugs... Es hat noch nicht einmal einen richtigen Namen! Diese Pest... wie Dunst - Hauch... Das ist es: PESTHAUCH! Dieser Pesthauch wird das Gewebe des Lebens selbst zersetzen!\n\n<Harris reicht Euch eine Phiole.>\n\nNun gut, findet den Fledermausführer Tobias und zeigt ihm diese Probe. Er wird Euch nach Gallgrimm bringen.", sourceObjective = "Zeigt Tobias Sarkhoff in Neu-Agamand die Pesthauchprobe.", progress = "Eine Lieferung extrem tödlichen Giftgases nach Gallgrimm? Kommt nur näher!", completion = "Ähm, ja, Ihr könnt die Phiole bei Euch behalten. Ihr habt mein Vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12182] = { id = 12182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Gallgrimm!", description = "Für dich habe ich eine spezielle Fledermaus aufgetrieben, <Kumpel/Süße>. Auf ihr wirst du den schnellsten und sanftesten Ritt haben, den ich dir bieten kann. Sie wird dich direkt nach Gallgrimm bringen - und das mit Stil.\n\nÜbergib dann einfach die Phiole an den obersten Seuchenfürsten Middleton, nachdem du gelandet bist.", sourceObjective = "Liefert die Pesthauchprobe beim obersten Seuchenfürsten Middleton ab. Er befindet sich in Gallgrimm im Osten der Drachenöde.", progress = "Ihr spielt also den Lieferjungen?", completion = "Oh, was für ein wundervoller Tag! Und seht, dort, gleich hinter dem Berg im Nordosten gibt es haufenweise Diener der Geißel, die wir ausradieren können!", sourceObjectiveStatus = "unverified-source-field" }
quests[12183] = { id = 12183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überzeugende Verkleidung", description = "Wenn, wie Ausgrabungsleiterin Varana behauptet, manche Eisenzwerge mit diesem Loken kommunizieren können, dann sind es bestimmt die Vorarbeiter, denen dieses Privileg zukommt.\n\nWir müssen Euch da reinbekommen, damit Ihr rausfindet, was es damit auf sich hat, aber das wird nicht leicht. Zunächst braucht Ihr die richtige Uniform.\n\nDanach machen wir uns über das richtige Make-up Gedanken.\n\nFindet einen der Vorarbeiter in Dun Argol, tötet ihn und nehmt seine Uniform mit. Wenn Blut daran klebt, dann ist es Eure eigene Schuld.", sourceObjective = "Bringt eine Aufseheruniform zu Gebirgsjäger Kilian im Prospektorat.", progress = "Habt Ihr die Uniform bekommen?", completion = "<Kilian nimmt Euch die Uniform ab.>\n\nDamit sollte es klappen. Es bleibt keine Zeit, noch ein Namensschild mit '{name}' anzunähen, aber wenn wir mit Euch fertig sind, sollte jeder, der Euch aus der Nähe betrachtet, Euch für einen echten Vorarbeiter halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12184] = { id = 12184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fotosafari", description = "Nun, da wir die Uniform haben, brauchen wir noch einige Informationen, um Eure Verkleidung perfekt zu machen.\n\nRaegar hat diese Kamera mitgebracht, um die Entdeckungen des Teams zu dokumentieren, aber ich habe eine andere Verwendung im Sinn. Ich möchte, dass Ihr sie mit nach Dun Argol nehmt und mit ihr Bilder von den Eisenzwergen macht.\n\nNatürlich werden Eure Modelle nicht sonderlich kooperativ sein, daher müsst Ihr sie eventuell zunächst, ähm... \"beruhigen\". Bringt die Kamera mit den Bildern zurück, wenn Ihr fertig seid.", sourceObjective = "Benutzt Kilians Kamera, um Bilder von 8 Eisenzwergen in Dun Argol aufzunehmen. Dann kehrt zu Gebirgsjäger Kilian im Prospektorat zurück.", progress = "Habt ihr die Schnappschüsse gemacht?", completion = "Gut, das sollte ausreichen. Nun werde ich eine Verkleidung anfertigen können, die Euch zu einem waschechten Eisenzwerg machen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12185] = { id = 12185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt Eure beste Miene auf für Loken", description = "Mithilfe der Bilder, die Ihr gemacht habt, habe ich alles zusammenbekommen, was Ihr für Eure Aufseherverkleidung braucht. Ihr werdet einen feinen Eisenzwerg abgeben, wenn ich das mal sagen darf.\n\nNehmt die Verkleidung mit nach Dun Argol, verkleidet Euch damit und geht zum östlichsten Gebäude in der breiten mittleren Ebene der Stadt.\n\nDort solltet Ihr ein Podest sehen, wo der Than und die Vorarbeiter ihre Befehle von Loken erhalten. Aktiviert es, während Ihr verkleidet seid und erfahrt so viel wie möglich aus der Kommunikation.", sourceObjective = "Verkleidet Euch als Eisenrunenaufseher, fangt die Nachricht von Loken ab und kehrt dann zu Gebirgsjäger Kilian im Prospektorat zurück.", completion = "Könnte es sein, dass Loken tatsächlich nicht übertreibt? Die Steine der Titanen und die Eisensöhne kämpfen gegeneinander um die Kontrolle der antiken Stadt Ulduar. Das ist Wahnsinn, {name}, und es könnte unsere einzige Chance, die wahre Geschichte über das Volk der Zwerge zu erfahren, zunichtemachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12186] = { id = 12186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flagge: Sieger" }
quests[12187] = { id = 12187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flagge: Teilnehmer" }
quests[12188] = { id = 12188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seuche der Verlassenen und du: Wie man nicht stirbt", description = "Wie genau nun die Seuche funktioniert, ist wohl kaum wichtig. Alles, was Ihr wissen müsst, ist, dass sie genau das macht, für was sie geschaffen wurde. Ich habe es zuwege gebracht, einen inaktiven Erregerstamm der Seuche künstlich herzustellen.\n\n<Middleton entkorkt die Phiole, setzt sie an die Nase und atmet ein.>\n\nSeht, mein Körper ist - zumindest größtenteils - unversehrt. Würdet Ihr das nun mit einem Agens vermischen, wären wir alle nichts weiter als ein Haufen klebriger Masse.\n\nAm Strand südlich von hier befinden sich die lächerlichen Geister einstiger Soldaten der Allianz. Zerstört sie und bringt mir ihre ektoplasmischen Überreste.", sourceObjective = "Oberster Seuchenfürst Middleton in Gallgrimm in der Drachenöde möchte, dass Ihr ihm 10 ektoplasmische Überreste bringt.", progress = "Die Überreste werden als Agens zur Aktivierung der Seuche dienen!", completion = "Das wird reichen, {name}. Haben sich diese lächerlichen Welpen Euch gestellt oder haben sie Euch lediglich mit geisterhaften Sorgentränen überschüttet?\n\nAh, sie sind so ergreifend...", sourceObjectiveStatus = "unverified-source-field" }
quests[12189] = { id = 12189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwachköpfe, wo man nur hinsieht!", description = "Die Lieferung aus Neu-Agamand hätte schon letzte Woche in Gallgrimm ankommen und nach ein paar einfachen Feldversuchen bei mir abgeliefert werden sollen. Hierbei handelt es sich um etwas, das für die Horde unerlässlich ist - um den letzten Teil des \"Siegesmosaiks\" sozusagen.\n\n<Sintar seufzt.>\n\nEs ist ziemlich entmutigend, nur von Schwachköpfen und Trotteln umgeben zu sein!\n\nGeht nach Gallgrimm gleich an der östlichen Grenze der Drachenöde. Findet diesen Kasper Middleton und lasst ihn wissen, dass ich auf das Paket warte.", sourceObjective = "Reist nach Gallgrimm in der Drachenöde und sprecht mit dem obersten Seuchenfürsten Middleton.", completion = "Wir sind auf ein kleines Problem gestoßen - ist auch NUR nebensächlich. Jeder, der mit der Seuche arbeiten wollte, ist einfach verdampft. Wir arbeiten gerade daran, die Formel ein klein wenig anzupassen, damit sie einen nicht gleich umbringt, wenn man auch nur einen Blick darauf werfen sollte. Die gute Neuigkeit ist, dass ich schon fast fertig bin!", sourceObjectiveStatus = "unverified-source-field" }
quests[12190] = { id = 12190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt hallo zu meinem kleinen Freund", description = "Harkor wird hin und weg sein, wenn er diese erstklassig'n Zutat'n sieht. Das Einzige, was es noch zu tun gibt, is', sie zu ihm zu bringen.\n\nEr hat sein Lager anner östlichen Küste inner Nähe dieser spukenden Ruinen - Drakil'jin werd'nse genannt. Ihr werdet wahrscheinlich eher dort ankommen, weil ich mich um diese Leichen hier kümmern muss... außer, Ihr möchtet Euer Glück lieber beim Einbalsamieren versuch'n.", sourceObjective = "Prigmon möchte, dass Ihr Harkors Zutaten zu Harkor in Harkors Lager bringt.", progress = "Was kann ich für Euch tun?", completion = "Nun denn! Der gute alte Prigmon hat Euch geschickt, nich' wahr?\n\nDas sollte genug für ein mächtig leck'res Essen sein. Fehlen nur noch ein paar Kleinigkeiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[12191] = { id = 12191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haut weg das Zeug!", description = "Hey, Ihr seht aus, als hättet Ihr Schmackes im Arm!\n\nWir sorgen im Lager gerne für gute Stimmung und da geht doch nichts über eine gute, alte Runde Krugelstoßen!\n\nIhr glaubt, Ihr hättet das Zielvermögen, A.L.K. treffen? Schnappt Euch einen Freibierkrug, genehmigt Euch einen Schluck und schaut, ob Ihr einen Treffer landet. Ist schwieriger, als es aussieht, aber das ist ja der Spaß an der Sache. Tretet ruhig ran und versucht es mal!", sourceObjective = "Trefft A.L.K. fünfmal mit dem Krug alkoholfreies Braufestbier.", progress = "Ext den Krug und werft ihn dann auf A.L.K.! Ich denke, die Schläge machen ihr nichts aus. Sonst hätte ich sie ja nicht gestoh... äh... gebaut.", completion = "Wow... A.L.K. ist nicht kaputt gegangen... Hm... Wer hätte das gedacht?\n\nIch meine, hey, Ihr habt es geschafft! Eure Zielfertigkeit ist gut, zumindest gut genug, um bei der Verteidigung des Lagers zu helfen. Ich glaube, Ihr seid nun bereit, den Dunkeleisenzwergen gegenüberzutreten, wenn sie wieder aufkreuzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12192] = { id = 12192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dieses eine Mal, als ich betrunken war...", description = "Die Dunkeleisenzwerge haben einstecken müssen! Als sie zurück zum Grimmigen Säufer rannten, fiel ein Teil ihrer Ladung herunter. Was jedoch noch viel wichtiger ist: Dank Euch ist das Lager außer Gefahr... zumindest für heute.\n\nGeht zu Bissel und erzählt ihm von Eurem heldenhaften Sieg über die Dunkeleisenzwerge.", sourceObjective = "Sprecht mit Bissel Schnellhub im Braufestlager.", completion = "Ihr konntet die Dunkeleisenzwerge also aufhalten... und wart dazu noch betrunken? Genau das ist es, {class}, worum es beim Braufest geht! Und wo wir schon mal dabei sind: Denke mal, dass Ihr Eure Biermarken haben wollt.\n\nDanke für Eure Hilfe, {name}. Weiterhin noch viel Spaß auf dem Braufest.", sourceObjectiveStatus = "unverified-source-field" }
quests[12193] = { id = 12193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt mal, es gibt dieses Jahr nicht zufällig ein Souvenir?", description = "Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.\n\nNaja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12194] = { id = 12194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt mal, es gibt dieses Jahr nicht zufällig ein Souvenir?", description = "Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.\n\nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12195] = { id = 12195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unerwarteter \"Gast\"", description = "Eine kürzlich zurückgekehrte Jagdexpedition hat mehr als nur Wild ins Lager gebracht.\n\nSie sind auf einen verwundeten Zwerg gestoßen, der vor den Eisenzwergen aus der Feste von Dun Argol geflohen war. Er könnte Informationen haben, die wir gegen unseren uralten Feind verwenden können, aber bevor er von Nutzen für uns sein kann, müssen wir sein Fieber in den Griff bekommen.\n\nDie Geweihe des Silberfellhirschs, der in den nahen Wäldern zu finden ist, werden seit Langem zur Herstellung von Heilpackungen verwendet. Bringt mir genügend Geweihe, dann sehen wir mal, ob meine Heilpackung unseren 'Gast' wieder auf die Füße bekommt.", sourceObjective = "Bringt 5 ausgewachsene Hirschgeweihe zu Tormak dem Vernarbten in Camp Oneqwah.", progress = "Habt Ihr die Geweihe dabei?", completion = "Das sollte reichen. Schauen wir mal, ob es funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12196] = { id = 12196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Grund auf", description = "Es bleibt nicht mehr genug Zeit, die Teile selbst zu schmieden, aber die Gießereien drüben in Dun Argol, südöstlich von hier, arbeiten Tag und Nacht und stellen Golemteile am laufenden Band her.\n\nIch glaube, Ihr solltet dorthin zurückgehen und genug davon einpacken, damit ich nach diesen Blaupausen einen Golem herstellen kann.\n\nVermutlich liegen sie um die Gebäude herum verstreut, in denen die Eisenrunenschmiede arbeiten.\n\nBitte beeilt Euch, {name}. Dieser Tormak wartet nur darauf, seine Drohung wahrmachen zu können!", sourceObjective = "Bringt Ausgrabungsleiter Rokar im Camp Oneqwah 8 Teile eines Kriegsgolems.", progress = "H-habt Ihr d-diese Golemteile mitgebracht?", completion = "<Rokar wischt sich mit dem Handrücken über die Stirn.>\n\nOh, dem Licht sei Dank. Er hat mir angedroht, mir kein Essen zu geben, bis Ihr zurück seid. Lasst uns diesen Stapel Teile sortieren und sehen, was wir daraus machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12197] = { id = 12197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben die Macht", description = "Gut, nun haben wir die Hülle eines Golem, aber das reicht Tormak noch nicht. Er sieht nicht ein, dass diese Dinge sich nicht einfach von selbst zusammensetzen und magisch zu funktionieren anfangen! Wir brauchen Energiezellen, um ihn zum Leben zu erwecken.\n\nAls ich in Dun Argol war, ist mir aufgefallen, dass die Runenschmiede Durar und Kathorn diejenigen waren, die die Zellen angefertigt haben. Wir brauchen je eine Zelle von beiden, um unseren Golem aufzuladen.\n\nIhr solltet die Runenschmiede in ihren Werkstätten in der zentralen Ebene von Dun Argol finden.", sourceObjective = "Bringt Durars Energiezelle und Kathorns Energiezelle zu Ausgrabungsleiter Rokar im Camp Oneqwah.", progress = "Habt Ihr diese Energiezellen?", completion = "<Rokar nimmt Euch die Batterien ab.>\n\nSie sind fast leer, aber es wird ausreichen, um den Golem aufzuladen. Damit ist er aber noch lange nicht bereit für einen Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[12198] = { id = 12198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... oder vielleicht doch nicht", description = "Die Zellen des Golems haben gerade genug Energie, um auf unterster Stufe zu laufen, doch für die Kampfsysteme reicht es nicht.\n\nDie gute Nachricht ist, dass die Umgebung von Dun Argol von Blitzwachen bewacht wird. Mit deren Hilfe sollten wir in der Lage sein, die Waffensysteme des Golems aufzuladen.\n\nNehmt den Golem mit, bringt ihn nah an sie heran, wenn die Wachen sterben, wird er ihre Energie absorbieren.", sourceObjective = "Ladet Euren Kriegsgolem mit der Energie von 10 Blitzwachen auf und kehrt dann zu Ausgrabungsleiter Rokar in Camp Oneqwah zurück.", completion = "Nun kann sich Tormak nicht mehr beschweren. Mehr kann ich an dem Golem nicht mehr machen.\n\nSobald Ihr mit ihm eine Schneise durch Dun Argol geschlagen habt, wird mich diese zu groß geratene Kuh wohl gehen lassen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12199] = { id = 12199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit dem Eisenthan!", description = "Da der Golem nun vollständig aufgeladen ist, kann er gegen den Anführer in Dun Argol eingesetzt werden.\n\nAls ich Eisenthan Zornhammer observiert habe, wurde er stets von einem persönlichen Golem beschützt, der ihn von jeglicher Gefahr ferngehalten hat.\n\nDiese Konstruktion namens \"der Amboss\" kann sabotiert werden, so dass er seinen Schild fallenlässt. Benutzt die EMP-Fähigkeit Eures Golems, um genau das zu tun. Ihr solltet Euren Golem innerhalb Dun Argols aktivieren und kontrollieren können.\n\nDer Than hält sich oben im Hauptgebäude auf und überwacht von dort aus die Produktion unten.", sourceObjective = "Besiegt den Eisenthan Zornhammer mithilfe Eures Kriegsgolems und kehrt dann zu Tormak dem Vernarbten im Camp Oneqwah zurück.", completion = "Also hat der Ausgrabungsleiter sein Versprechen wahr gemacht? Gut. Ich habe mich schon gefragt, ob all dies Schnorren von Metallstücken und Klauen von Baumaterial zu irgendwas führen würde.\n\nEs ist eine Schande, dass er uns nicht mehr nützlich sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12200] = { id = 12200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragddrachentränen", description = "Da nun das inaktive Exemplar des Seuchenpräparats fertiggestellt ist und wir das Aktivierungsagens in Händen halten, fehlt uns nur noch eine passende Hülle für die Komponenten.\n\nSüdwestlich von hier an der zentralen Küste der Drachenöde liegt der Smaragddrachenschrein. Im Inneren des Schreins findet Ihr die hart gewordenen Überreste der Träne eines grünen Drachen. Ich kenn' zwar nicht die ganze Geschichte, aber anscheinend weinen sie sehr viel, bevor sie sterben – stellt Euch vor.\n\nGeht zum Smaragddrachenschrein und sammelt Tränen.", sourceObjective = "Oberster Seuchenfürst Middleton in Gallgrimm in der Drachenöde möchte, dass Ihr 8 Smaragddrachentränen sammelt.", progress = "Glücklicherweise befindet sich ein Ort in der Nähe, in dem es mehr als genug Smaragddrachentränen gibt. Ansonsten hätte ich Euch nach Feralas schicken müssen.", completion = "Ich glaube, dass wir die Seuche jetzt einem Feldversuch unterziehen können. Zufälligerweise wird die Feste Wintergarde gerade von der Zitadelle des Schreckens Naxxramas belagert. Nun kommen die lebenden Toten aus genau dem Boden hervor, auf dem Wintergarde erbaut wurde - begierig darauf, Kel'Thuzads Befehle auszuführen.\n\nDie Allianz ist, wie könnte es anders sein, zahlenmäßig und an Waffenkraft unterlegen. Die Leute, die im Mausoleum von Wintergarde ihre letzte Ruhe gefunden haben, wachen von Neuem auf und es verlangt ihnen nach Fleisch!\n\nVielleicht sollten wir ihnen mal eine Kostprobe unserer Seuche bescheren, was meint ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[12201] = { id = 12201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Aufsehers Schatten", description = "Hört sich an, als sei dieser Loken der Drahtzieher hinter den plötzlichen Kriegsvorbereitungen der Eisenzwerge.\n\nNur die höchstrangigen Eisenzwerge haben für gewöhnlich Zugang zu ihm, deshalb müssen wir Euch wohl zu einem Aufseher machen, um herauszufinden, was dort vor sich geht.\n\nIch habe einen Plan dafür, jedoch brauchen wir ein paar Sachen.\n\nSucht einen der Eisenrunenaufseher in Dun Argol im Südosten und nehmt ihm seine Uniform ab.", sourceObjective = "Bringt eine Aufseheruniform zu Späher Vor'takh in Oneqwah.", progress = "Habt Ihr die Uniform besorgt?", completion = "Das sollte funktionieren, jedoch bleibt da noch die Frage nach dem Rest der Verkleidung. Selbst diese verblödeten Metallzwerge erkennen einen Schwindler in einer gestohlenen Uniform.", sourceObjectiveStatus = "unverified-source-field" }
quests[12202] = { id = 12202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fotosafari", description = "Jetzt müssen wir nur noch letzte Handgriffe anlegen, um Euch genauso abstoßend hinzukriegen, wie es die Eisenzwerge sind.\n\nAm ehesten schaffen wir das, indem wir Eure Verkleidung an den Visagen der echten Eisenzwerge ausrichten.\n\nAls Tormaks Jagdgruppe diesen missratenen Ausgrabungsleiter gefunden hat, haben sie ihm gleich mal die Kamera, die er dabei hatte, abgenommen. Jetzt ist wohl die Zeit gekommen, sie zu benutzen.\n\nNehmt sie mit nach Dun Argol, tötet einige Eisenzwerge und bannt ihre Visagen auf dieses Gerät. Bringt es zurück, sobald Ihr genügend Exemplare habt.", sourceObjective = "Benutzt Rokars Kamera, um in Dun Argol die Bilder von 8 Eisenzwergen aufzunehmen und kehrt dann zu Späher Vor'takh im Camp Oneqwah zurück.", progress = "Habt Ihr diese Schnappschüsse?", completion = "Das sollte reichen. Bei Garrosh, sind diese Kreaturen abstoßend!", sourceObjectiveStatus = "unverified-source-field" }
quests[12203] = { id = 12203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokens Befehle", description = "Ich habe auch alles Andere, was Ihr für Eure Aufseherverkleidung benötigt, hergestellt. Bitte, versucht nicht zu würgen, wenn Ihr sie anlegt.\n\nNehmt die Sachen mit, wenn Ihr in den Südosten nach Dun Argol geht, benutzt sie, um Euch zu verkleiden, und geht dann zu dem Gebäude im äußersten Osten auf der breiten mittleren Ebene der Stadt.\n\nDort solltet Ihr ein Podest sehen, auf welchem der Than und die Aufseher ihre Befehle von Loken erhalten. Aktiviert es, während Ihr verkleidet seid, und sammelt so viele Informationen wie möglich.", sourceObjective = "Verkleidet Euch als Eisenrunenaufseher, fangt die Nachricht von Loken ab und erstattet dann Späher Vor'takh im Camp Oneqwah Bericht.", completion = "Er hat also vor, einen Bürgerkrieg zwischen den verschiedenen titanischen Schöpfungen heraufzubeschwören? Warum bedeutet ihm die Titanenstadt Ulduar so viel? Ich nehme an, dass es dies ist, was Kurun und seine Riesen zu verhindern hoffen.\n\nNun ja, ich bezweifle, dass wir die Riesen davon abhalten können, einander zu bekämpfen, aber möglicherweise finden wir einen Weg, dies zu unserem Vorteil zu nutzen. Ich muss sofort unseren Anführern Bericht erstatten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12204] = { id = 12204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Lokens Namen", description = "Die Eisenzwerge sind einer der erbittertsten und organisiertesten Gegner in Nordend. Wo auch immer wir hingekommen sind, haben sie uns mit dem Namen Lokens auf den Lippen bekämpft.\n\nWir müssen herausbekommen, wer dieser Loken ist und was er vorhat. Die Einheimischen könnten uns weiterhelfen.\n\nIm Nordosten, im Handelsposten von Rotholz, bietet ein Mensch namens Hugh Glass seine Waren feil. Weiter östlich, bei den Ruinen von Tethys, findet Ihr einen Steinriesen, der Gavrock genannt wird. Fragt sie nach diesem Loken. Sie müssen einfach irgendwelche brauchbaren Informationen haben.", sourceObjective = "Sprecht mit Hugh Glass und Gavrock über Loken und übermittelt Eure Erkenntnisse Späher Vor'takh im Camp Oneqwah.", completion = "Also ist er der Strippenzieher bei den Eisenzwergen? Wir müssen herausfinden, was er den Eisenzwergen von Dun Argol befohlen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12205] = { id = 12205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Der Scharlachrote Ansturm", description = "Auf Befehl des Hochexekutors Zürner sind alle Mitglieder der illegalen Organisation genannt \"der Scharlachrote Ansturm\" auf der Stelle zu töten.\n\nIhnen ist keine Gnade zu gewähren. Diejenigen, die aufgrund dieses Erlasses zur Tat schreiten werden, sollten darüber im Klaren sein, dass der Tod noch das Mildeste ist, was man erwarten kann, sollte man von den Menschen gefangen genommen werden!\n\nUm es in den Worten des Hochexekutors auszudrücken: \"Färbt den Schnee rot mit ihrem Blut!\"", sourceObjective = "Tötet 20 Mitglieder des Scharlachroten Ansturms und meldet Euch anschließend bei Hochexekutor Zürner in Gallgrimm.", completion = "Sehr gut gemacht, {race}. Ich vertraue einmal darauf, dass Ihr mit viel Geschick zu Werke gegangen seid.\n\nDann lasst uns mal sehen, wie viel die Toten - ähm - ich meine, wie viel die Truhen Euch einbringen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12206] = { id = 12206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verseuchte letzte Riten", description = "Habt Ihr den Steckbrief gelesen? Was denkt sich der Hochexekutor nur?!\n\n<Vicky sieht sich um und fährt mit gedämpfter Stimme fort.>\n\nWir können doch wohl nicht zulassen, dass diese Idioten vom Scharlachroten Ansturm von ihren Priestern wiedererweckt werden oder - schlimmer noch - als Diener der Geißel wieder auferstehen, nicht wahr?\n\nNein, ich stimme Euch völlig zu, wir müssen etwas gegen die Leichen unternehmen.\n\nIch hab' genau das nötige Werkzeug. Nehmt dieses Fläschchen an Euch, in ihm befindet sich die erst kürzlich von uns hergestellte Seuche, und testet dessen Inhalt an dem Gefangenen in dem Käfig hier aus.\n\nKeine Aufregung, einfach zurücklehnen und zugucken - und siehe da: keine Feinde, die wieder auferstehen können.", sourceObjective = "Apothekerin Vicky Levine in Gallgrimm möchte, dass Ihr das Seuchenfläschchen an dem Gefangenen des Scharlachroten Ansturms austestet.", completion = "WAS?! Das ist unmöglich! Wir haben die Seuche perfektioniert. Sie ist zu hundert Prozent tödlich.\n\n<Die Apothekerin ringt die Hände - Besorgnis steht in ihrem untoten Gesicht geschrieben. Sie ist ganz offensichtlich frustriert und mit Zorn in ihrer Stimme fährt sie fort.>\n\nDas ist einfach nur seltsam. Reicht mir das Fläschchen, {class}. Ich werde auf keinen Fall die Apothekerin sein, die alles zum Scheitern brachte!", sourceObjectiveStatus = "unverified-source-field" }
quests[12207] = { id = 12207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassils Fall", description = "Vor langer Zeit pflanzten mächtige Druiden einen Baum nordöstlich von hier.\n\nEr wurde Vordrassil genannt und sollte zu einem Weltenbaum erwachsen. Es ist nicht bekannt warum, aber nachdem der Baum vollständig ausgewachsen war, entschieden die Druiden, dass er zerstört werden müsse.\n\nSeit dem Moment, an dem wir hier angekommen sind, hat die Erde zu mir gesprochen, {name}. Ihre Schmerzenslaute kommen von den Orten, an dem Vordrassils Überreste den Boden berührten.\n\nFauliger Schlamm ist dort zu finden. Bringt mir Proben davon, sodass wir damit beginnen können, dieses Land zu heilen.", sourceObjective = "Windseherin Grauhorn in Burg Siegeshall möchte, dass Ihr zu Vordrassils Ast, Vordrassils Herz oder Vordrassils Tränen geht und 6 Schleimproben des entropischen Schlamms besorgt.", progress = "Habt Ihr die Proben sammeln können, {name}?", completion = "Dieser Schleim stinkt nach einer Finsternis, die viel älter ist, als ihre weltliche Form einen annehmen lassen würde. Das Land selbst erinnert sich an dieses Böse, seitdem es existiert.\n\nWir müssen mehr herausfinden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12208] = { id = 12208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Trolljagd", description = "Diese nichtsnutzigen Mistkerle!\n\nSie hätten es einfacher haben können. Wir haben ihnen die Hand zum Frieden gereicht. Alles, was sie hätten tun müssen, ist, uns den Durchgang durch Drak'Tharon zu gewähren, und wir hätten sie in Ruhe gelassen.\n\nDoch nein, die hochmütigen kleinen Eistrolle wollen es anscheinend auf die harte Tour. Wir werden so oder so durch ihre kostbare Festung marschieren, um nach Zul'Drak zu gelangen. Doch nun werden sie vernichtet werden.\n\nWir haben eine Bande angeheuert, die für uns Trolle einfangen soll. Sprecht mit Samir, wenn Ihr bei der Sache mitmischen wollt. Ihr könnt ihn nordwestlich von hier, südlich von Zeb'Halak finden.", sourceObjective = "Unteroffizier Thurkin möchte, dass Ihr mit Samir am Granitquell sprecht.", completion = "Ihr seid hier, um bei der Kopfgeldangelegenheit mitzumischen, wie?", sourceObjectiveStatus = "unverified-source-field" }
quests[12209] = { id = 12209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsbeute", description = "Ah gut, Frischfleisch. Wollt Ihr Euch bewähren, Frischfleisch?\n\nDer Scharlachrote Ansturm, die fanatischste und rassistischste Gruppe des Scharlachroten Kreuzzuges, steht vor unserer eigenen Haustüre - im Süden. Wenn wir sie bekämpfen wollen, werden wir mehr Rüstungen und Waffen benötigen, als ich in so kurzer Zeit überhaupt herstellen kann.\n\nWieso schnappen wir uns nicht einfach ihre Waffen?\n\nGenauer gesagt: Wieso schnappt IHR EUCH nicht einfach ihre Waffen?", sourceObjective = "Quartiermeister Bartlett in Gallgrimm möchte, dass Ihr 8 Rüstungen des Scharlachroten Ansturms und 8 Waffen des Scharlachroten Ansturms stehlt.", progress = "Ich nehme, was auch immer Ihr mir an Rüstungen und Waffen besorgen könnt, Frischfleisch.\n\nQualitativ gesehen werden sie zwar nicht an das heranreichen, was ich hier herstellen kann, doch sie sind besser als gar nichts.", completion = "So frisch riecht Ihr gar nicht mehr, Frischfleisch.\n\nNun gut, das wird wohl reichen. Wie soll ich Euch nun nennen, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[12210] = { id = 12210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollsaison!", description = "Ihr, {race}! Was für eine Verschwendung, hier herumzustehen, während es dort draußen noch Arbeit zu tun gibt!\n\nDie Feste Drak'Tharon ist der direkteste Weg nach Zul'Drak. Wir MÜSSEN sie einnehmen, um dafür zu sorgen, dass die Allianz dort sicher ankommt. Doch bis wir die nötigen Leute für einen Angriff zusammenhaben, müssen wir uns damit begnügen, die Reihen der Eistrolle zu lichten und Informationen zu sammeln.\n\nFür letzteres haben wir eine Bande von Rohlingen eingezogen, die lebendige Trolle einfangen und dann zwecks Vernehmung hierher bringen sollen. Reist nach Nordwesten und sprecht mit Samir am Granitquell. Er wird Euch sagen, wie es weitergeht.", sourceObjective = "Leutnant Dumont bei der Ammertannhütte möchte, dass Ihr mit Samir am Granitquell sprecht.", completion = "Ihr seid hier, um bei der Kopfgeldangelegenheit mitzumischen, oder was?", sourceObjectiveStatus = "unverified-source-field" }
quests[12211] = { id = 12211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie nicht wieder auferstehen!", description = "Ich verstehe es einfach nicht. Es sollte mit der Seuche doch eigentlich funktionieren.\n\nAber Jammern hat keinen Sinn.\n\n<Aus irgendeinem Grund wirkt die Apothekerin erleichtert.>\n\nObwohl es merkwürdigerweise beim Ansturm nicht zu wirken scheint, müssen wir nach wie vor ihre Priester davon abhalten, sie wiederzuerwecken.\n\nIch habe eine andere Idee - eine, vor der Ihre Leichname keinen Schutz haben sollten.\n\nNehmt einen Behälter mit Ratten, {name}, und lasst sie auf jede Leiche des Scharlachroten Ansturms los, die ihr finden könnt. Ich habe das Gezücht hungern lassen - also sollten sie besonders garstig sein!", sourceObjective = "Apothekerin Vicky Levine aus Gallgrimm hat Euch gebeten, Ihr Behältnis voller Ratten zu benutzen, um 15 Leichen von Anhängern des Scharlachroten Ansturms in Neuherdweiler zu beseitigen.", completion = "Sehr gut! Einen Moment lang dachte ich schon, ich müsste die Ratten an jemandem ausprobieren, um sicherzustellen, dass sie nicht defekt sind.\n\nEndlich ein Fortschritt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12212] = { id = 12212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Lagerhaus auffüllen", description = "Guten Tag, {class}.\n\nDer gute Leutnant hier meint, dass die Horde unser Lagerhaus geplündert hätte, wodurch unser Essensvorrat nun gefährlich klein geworden sei.\n\nDiese Schwachköpfe werden dafür auf jeden Fall büßen, doch zuerst müssen wir unsere Aufmerksamkeit darauf richten, unsere Vorräte wieder aufzufüllen. Meine Männer tun alles, was in ihrer Macht steht, doch wir werden jeden benötigen, der etwas beitragen kann, wenn wir eine Krise verhindern wollen.\n\nEs sollte keine Schwierigkeiten darstellen, die Hirsche in dieser Gegend zu erlegen, um an deren Fleisch heranzukommen. Frohe Jagd!", sourceObjective = "Forstmeister Anderhol bei der Ammertannhütte möchte, dass Ihr Großhornhirsche tötet und 8 Stück saftiges Wildbret sammelt.", progress = "Wie läuft die Jagd, {race}?", completion = "Das ist doch mal feinstes Fleisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[12213] = { id = 12213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunkelheit darunter", description = "Etwas… Dunkles… ist dem Baum Vordrassil zugestoßen. Nachdem die Druiden beschlossen hatten, ihn zu zerstören, bohrten seine hohlen Überreste ihre Wurzeln tief in den Boden.\n\nIch möchte, dass Ihr zu den drei Orten im Nordosten geht, wo der Stamm gesplittert ist und, so weit Ihr könnt, in den Untergrund vordringt.\n\nBenutzt diese Kugel, sobald Ihr eingetroffen seid, um die Spuren der Energie, welche die Gegend umgibt, anzeigen zu können. Dies könnte aufzuklären helfen, was mit Vordrassil damals passiert ist und warum er es nicht geschafft hat, ein Weltenbaum zu werden.", sourceObjective = "Windseherin Grauhorn möchte, dass Ihr zu Vordrassils Herz, Vordrassils Tränen und Vordrassils Ast geht und die Kugel des Geomanten in den Tiefen unter der Erdoberfläche anwendet.", completion = "Diese Kugel… sie wurde von einer... abgrundtief bösen Macht befleckt.\n\nWas ich auch sonst noch durch weitere Untersuchungen herausfinden werde, eines ist sicher: Ich muss die Kugel so bald als möglich zerstören. Ihre verderbende Macht ist einfach zu groß.", sourceObjectiveStatus = "unverified-source-field" }
quests[12214] = { id = 12214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzpferde", description = "Hallo, <mein Herr/meine Dame>. Ich bin Hänsel. Schön, Euch kennenzulernen.\n\nDer Hochexekutor kam zu mir und meinte: 'Hänsel, ich möchte, dass du uns ein paar neue Pferde beschaffst.'\n\nWas meint er denn, wo Schreckensrösser herkommen? Aus dem Boden?\n\n<Hänsel flüstert.> Auf Pferdefriedhöfen tun sie das sogar.\n\nNur gibt es hier keinen, also müsst Ihr nach Neuherdweiler im Süden gehen, die Ritter töten, ihnen die Reitgerten abnehmen und ihre Schlachtrösser stehlen.\n\nWäre gut, wenn Ihr dann mit dem Pferd zu mir reitet und mir die Zügel gebt.", sourceObjective = "Hänsel Bauer in Gallgrimm möchte, dass Ihr 3 Kriegspferde des Ansturms stehlt, sie anschließend bei ihm abliefert und ihm dann auch die Zügel übergebt.", progress = "Ich bin richtig erleichtert, dass Ihr hier aufgetaucht seid. Ich hatte schon Angst, dass ich die Sache selbst in die Hand nehmen muss.", completion = "Ah, gute Arbeit - nichts ist schöner als das.\n\nIhr habt Gallgrimm einen großen Dienst damit erwiesen, diese Pferde zu besorgen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12215] = { id = 12215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie oder wir!", description = "Als ob wir nicht schon genug hätten, das uns Sorgen bereitet...\n\nAufgrund der jetzigen Essenskrise befinden wir uns mit den hiesigen Worgs im Nahrungsstreit. Die Situation wird immer schlimmer und ich befürchte, dass es schon bald nichts mehr zu jagen geben wird, wenn wir uns nicht sofort diesem Problem zuwenden.\n\nDurchkämmt den Wald, {race}. Tötet alle Graunebeljäger, die Ihr finden könnt. Jüngste Berichte sprechen von einer Ansammlung dieser Wesen am anderen Ufer des westlich gelegenen Flusses.", sourceObjective = "Anderhol bei der Ammertannhütte möchte, dass Ihr in den Grizzlyhügeln nach 6 Graunebeljägern sucht und sie tötet.", completion = "Gute Arbeit, {class}.\n\nDas sollte uns dabei helfen, sicherzustellen, dass die Tiere in dieser Gegend auch dort landen, wo sie hingehören - nämlich auf dem Rost über unseren Feuern.", sourceObjectiveStatus = "unverified-source-field" }
quests[12216] = { id = 12216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärenhatz!", description = "Wir haben hart gearbeitet und so langsam sehen wir auch die Früchte dieser Arbeit, aber wir sind noch immer weit davon entfernt, unser Ziel zu erreichen. Wir brauchen viel mehr Fleisch als wir haben und die Hirschpopulation hier wird alleine nicht ausreichen.\n\nIch fürchte, Ihr müsst Eure Aufmerksamkeit etwas gefährlicherer Beute zuwenden... den Grizzlys, die dieser Gegend den Namen geben. Es gibt sie Zuhauf und sie sind wohlgenährt von den ganzen Fischschwärmen in diesen Gewässern.\n\nGebt auf Euch acht, {class}!", sourceObjective = "Anderhol bei der Ammertannhütte möchte, dass Ihr 8 Grizzlyflanken von den Grizzlybären in den Grizzlyhügeln ergattert.", progress = "Der mächtige {class} ist zurückgekehrt!", completion = "Hervorragend!\n\nUnser Vorratslager ist nun fast wieder voll. Ihr habt euren Beitrag dazu geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12217] = { id = 12217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adleraugen", description = "Nun, {name}, wir haben herausgefunden, wie die Horde unsere verborgenen Nahrungslager lokalisieren konnte.\n\nOffensichtlich war ihre Sicht an die der arglosen Adler gebunden, die hier über den Bäumen kreisen. Mit der Sicht der Adler war es ihnen tatsächlich möglich, jede unserer Handlungen zu beobachten.\n\nAuf Befehl des Leutnants sollen wir diese majestätischen Vögel erlegen, um unserem Feind einen Strich durch die Rechnung zu machen.", sourceObjective = "Anderhol bei der Ammertannhütte möchte, dass Ihr 5 Kaiseradler tötet und ihm anschließend Bericht erstattet.", completion = "Eine düstere Aufgabe, ich weiß. Aber wir können uns wieder sicherer fühlen, jetzt, da wir wissen, dass die Augen des Feindes nicht länger auf uns ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12218] = { id = 12218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitet die guten Neuigkeiten", description = "Bevor ich Euch mit den guten Neuigkeiten zu Doktor Malefius schicken kann, werdet Ihr einen einfachen Feldversuch der von mir modifizierten Seuche durchführen müssen.\n\nDie hungernden Toten strömen aus den Überresten von Altwintergarde. Beschlagnahmt eines der Gefährte am Osttor und fahrt mit ihm nach Nordosten durch den Pass der Vergeltung bis Ihr die Zwillingstürme in der südöstlichen Ecke von Wintergarde erreicht. Feuert die Seuchenbombe auf die Untoten ab, von denen es in der Gegend nur so wimmelt. Meldet Euch anschließend mit den Resultaten wieder bei mir zurück!", sourceObjective = "Oberster Seuchenfürst Middleton in Gallgrimm in der Drachenöde möchte, dass Ihr in den Seuchenverbreiter der Verlassenen steigt, zu den Randgebieten der Aasfelder fahrt und dort mithilfe der Seuchenbombe 30 hungernde Tote vernichtet.", completion = "So sehr es mich verärgert, dass wir der Allianz womöglich geholfen haben, erkläre ich hiermit den Feldversuch für erfolgreich! Nächster Halt: Agmars Hammer!", sourceObjectiveStatus = "unverified-source-field" }
quests[12219] = { id = 12219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der eingegangene Weltenbaum", description = "Meine Urahnen pflanzten einst einen Baum in der Mitte der Grizzlyhügel.\n\nVordrassil wurde er genannt und sollte ein Weltenbaum werden.\n\nAus Gründen, die schon lange in Vergessenheit geraten sind, beschlossen sie, den Baum zu zerstören, nachdem er seine volle Größe erreicht hatte. Seine Splitter befinden sich an drei verschiedenen Orten in der Gegend im Norden.\n\nDort, wo der Baum den Boden berührte, tauchte fauliger, lebendiger Schlamm auf. Bringt mir ein paar Schleimproben, damit ich mit meiner Arbeit beginnen und die Erde heilen kann.", sourceObjective = "Hierophantin Thayreen bei der Ammertannhütte möchte, dass Ihr zu Vordrassils Ast, Vordrassils Herz oder zu Vordrassils Tränen geht und 6 Schleimproben des entropischen Schlamms beschafft.", progress = "Habt Ihr die Proben gesammelt, {name}?", completion = "Der Schleim ist nicht natürlich, {name}. Er ist von Natur aus verderbt und... boshaft.\n\nWir müssen noch mehr darüber herausfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12220] = { id = 12220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dunkler Einfluss", description = "Als der Baum Vordrassil fiel, bohrten seine hohlen Überreste ihre Wurzeln tief in den Boden.\n\nIch möchte, dass Ihr nach Norden geht, die drei Orte aufsucht, wo der Stamm gesplittert ist, und so tief wie möglich in den Untergrund vordringt. Sie liegen westlich von Grauschlund.\n\nBenutzt diese Kugel, sobald Ihr eingetroffen seid, um die Spuren der Energie, welche die Gegend umgibt, anzeigen zu können. Wenn wir das Land heilen wollen, müssen wir zunächst herausfinden, was dazu geführt hat, dass Vordrassil vor all diesen Jahren als Weltenbaum versagt hat.", sourceObjective = "Hierophantin Thayreen bei der Ammertannhütte will, dass Ihr zu Vordrassils Herz, Vordrassils Tränen und Vordrassils Ast geht und die Kugel des Geomanten in den Tiefen unter der Erdoberfläche anwendet.", completion = "Die Energie in der Kugel ist… überwältigend… \n\nEine dunkle Macht hat den Boden bei Vordrassils Überresten befleckt. Wir müssen dies weiter untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12221] = { id = 12221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seuche der Verlassenen", description = "Ich habe ein Paket vorbereitet, das an Doktor Sintar Malefius in Agmars Hammer geschickt werden muss. Der Inhalt des Pakets besteht aus der fertigen Pesthauchprobe, zusammen mit der Herstellungsanleitung und Proben des Aktivierungsagens.\n\nIhr findet Agmars Hammer im Westen der Drachenöde. Haltet einfach nach den schwarzen, gezackten Metallgebäuden der Orcs Ausschau - das wird dann Agmars Hammer sein.", sourceObjective = "Liefert die Seuche der Verlassenen bei Doktor Sintar Malefius in Agmars Hammer ab.", progress = "Wurde auch langsam Zeit!", completion = "<Doktor Malefious wirft einen kurzen Blick auf den Inhalt des Pakets.>\n\nHerrlich! Genau nach Angabe!\n\nHier ist Eure Bezahlung, {name}. Behaltet das, was Ihr gesehen und getan habt, für Euch. Die Sache ist streng geheim - Informationen werden bei Bedarf weitergegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12222] = { id = 12222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Flammenbinder", description = "Während wir versuchen, die Horde zurückzuschlagen, sammelt sich der Stamm der Drachenschinder in ihrem Dorf Voldrune, in der Nähe der Küste im Süden.\n\nDen mächtigsten Kriegern im Dorf werden flammenerfüllte Talismane gewährt, die ihnen die Fähigkeit geben, mächtige, wilde Protodrachen zu kontrollieren. Wenn es uns gelänge, die Kontrolle über einen dieser Drachen zu übernehmen, dann könnten wir ihn vielleicht dazu nutzen, die Gefahr, die von Voldrune ausgeht, zu neutralisieren.\n\nDie Flammenbinderinnen der Drachenschinder erschaffen die Talismane und erfüllen sie mit Macht. Tötet sie und nehmt die Talismane.", sourceObjective = "Bringt dem Förster Drach bei der Ammertannhütte 3 flammenerfüllte Talismane.", progress = "Habt Ihr diese Talismane bekommen?", completion = "Mit diesen Talismanen in der Hand wird der Drache keine andere Wahl haben, als Euch zu gehorchen. Ich kann es kaum abwarten, den Gesichtsausdruck des Thans zu sehen, wenn er feststellt, dass Ihr das Kommando über seinen Protodrachen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12223] = { id = 12223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reihen lichten", description = "In Voldrune gen Süden geht es richtig zu. Thane Torvald Eriksson und seine Huscarls bereiten sich auf den Krieg vor. Ammertann wird verwundbar sein, da sich die meisten unserer Männer draußen im Feld befinden und sich um die verräterische Horde kümmern.\n\nReist nach Voldrune nahe der Südküste und zeigt diesen Drachenschindern, dass mit uns nicht zu spaßen ist.\n\nErschlagt so viele Huscarls, wie Ihr nur finden könnt. Sie sollen es sich zweimal überlegen, bevor sie unseren Konflikt mit der Horde ausnützen, um uns in den Rücken zu fallen.", sourceObjective = "Tötet 12 Huscarls der Drachenschinder und kehrt anschließend zu Förster Drach in der Ammertannhütte zurück.", completion = "Gut gemacht, {name}. Nun müssen wir die Sache nur noch zu Ende führen und uns den Vorteil zu Nutze machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12224] = { id = 12224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vorposten der Kor'kron!", description = "Gut gemacht, <Bruder/Schwester>. Ihr habt Euch allen Herausforderungen wie ein Champion der Horde gestellt: habt die verseuchten Anub'ar von Azjol-Nerub unter Euren Füßen zerquetscht! - habt die mutigen und mächtigen Taunka zu neuen Mitgliedern der Horde gemacht! - habt unsere neue Superwaffe gegen die Geißel getestet und perfektioniert!\n\nDie Zeit ist nun reif, der Moment ist gekommen: Unsere Elitesoldaten an der Pforte des Zorns brauchen Euch. Der Sohn von Saurfang im Vorposten der Kor'kron erwartet Eure Ankunft. Geht jetzt - auf nach Nordosten zur Pforte des Zorns.", sourceObjective = "Meldet Euch bei Saurfang dem Jüngeren im Vorposten der Kor'kron.", completion = "Lok'tar Ogar! Ich habe schon viel von Euch gehört, {name}. Die Narben aus Euren Schlachten sind tief - ein Zeichen Eurer Hingabe und Macht!\n\nDa der Lichkönig unsere West- und Ostflanke vernichtend geschlagen hat, bleibt nur noch unsere Streitmacht an der Pforte des Zorns übrig. Jeden Tag gewinnen wir an Boden und schon bald werden wir durch diesen Wall brechen und zur Eiskrone gelangen!\n\nSobald den Skelettdrachen Einhalt geboten wurde, werden Hochlord Fordragon und ich ins Feld ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12225] = { id = 12225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mmm... Bernsteinsamen!", description = "Euer Magen knurrt, als der starke Geruch herzhafter Nüsse Eure Aufmerksamkeit auf den mit Samen gefüllten Eimer zieht.\n\nIrgendeine aufmerksame Seele hat diese Gratisleckerbissen offensichtlich hier gelassen, um erschöpfte Besucher wieder frisch und munter zu machen. Dankbar tut Ihr Euch an den paar verbliebenen gütlich.\n\nDer Geschmack der Samen enttäuscht nicht. Ihr wollt noch mehr und macht Euch also auf den Weg, um herauszufinden, woher sie kommen...", sourceObjective = "Sprecht mit Forstmeister Anderhol in der Ammertannhütte.", completion = "Ihr habt was getan?!!\n\nDas waren Bernsteinsamen! Die Ausbeute einer ganzen Ernte!\n\nDiese magischen Samen waren womöglich die Antwort auf unsere Essenskrise. Ihr werdet das wieder richten, {name}, das könnt Ihr mir glauben!", sourceObjectiveStatus = "unverified-source-field" }
quests[12226] = { id = 12226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder raus damit", description = "Wir müssen schnell handeln, {race}! Wir können es nicht riskieren, dass diese wertvollen Samen vollständig verdaut werden. Sie müssen raus, und zwar JETZT!\n\nBesorgt ein paar Schwarzwurzeln vom Flussufer westlich von hier und ich werde Euch ein Abführmittel zubereiten, das die Sache ins Rollen bringen sollte.\n\nBeeilt Euch! Und denkt dran, Ihr habt Euch das selbst eingebrockt...", sourceObjective = "Anderhol bei der Ammertannhütte möchte, dass Ihr ihm 5 Schwarzwurzelstrünke bringt.", progress = "Habt Ihr die Schwarzwurzel gefunden?", completion = "Mit denen hier sollte es gut klappen…\n\n<Anderhol bricht geschickt die Strünke auf und sammelt die austretende Flüssigkeit in einer kleinen Phiole.>\n\nSo, und jetzt zur Sache.", sourceObjectiveStatus = "unverified-source-field" }
quests[12227] = { id = 12227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tut Eure Pflicht", description = "In Ordnung, {race}. Hier ist der Saft.\n\nDie Wirkung tritt sofort ein, benutzt ihn deshalb erst, wenn Ihr sicher das Plumpsklo erreicht habt.\n\nUnd jetzt besorgt mir diese Samen!", sourceObjective = "Anderhol bei der Ammertannhütte möchte, dass Ihr Anderhols Karussellstöffsche nehmt und das nahegelegene Plumpsklo aufsucht, um die teilweise verarbeiteten Bernsteinsamen zurückzuholen.", progress = "Na, habt Ihr diese Samen für mich, {race}?", completion = "Nun, {name}? Alles gut rausgekommen?\n\nHmm, sieht so aus, als hätten wir sie gerade noch rechtzeitig retten können…", sourceObjectiveStatus = "unverified-source-field" }
quests[12228] = { id = 12228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich der Magie wieder bemächtigen", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[12229] = { id = 12229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine mögliche Verbindung", description = "Vor nicht allzu langer Zeit haben wir eine Expedition in den Osten entsandt, wo sie von wahnsinnigen Furbolgs angegriffen wurde. Einer der Überlebenden beschrieb uns, wie er einen von ihnen erschlug und aus dessen Körper eine dunkle, schleimige Substanz austrat.\n\nTausende von Jahren waren die Furbolgs in dieser Gegend friedlich. Es ist möglich, dass eine Verbindung besteht zwischen dem Verhalten der Furbolgs und der dunklen Energie, die wir zuvor entdeckt haben.\n\nBringt mir ein paar Proben des Furbolgbluts. Ihr findet sie im Osten am Schrein des Grollfangs und am Schrein des Herzbluts.", sourceObjective = "Windseherin Grauhorn in der Burg Siegeswall möchte, dass Ihr 8 Proben des Bluts eines wahnsinnigen Furbolgs von den Furbolgs am Schrein des Herzbluts und am Schrein des Grollfangs sammelt.", progress = "Habt Ihr die Blutproben, {name}?", completion = "Dieses Blut scheint auf dieselbe Art verdorben zu sein wie der Schleim, den Ihr zuvor gesammelt habt… Dies lässt nichts Gutes erahnen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12230] = { id = 12230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von den Belagerungsschmieden klauen", description = "Ich bin mit der Zerstörung der Ballisten des Scharlachroten Ansturms beauftragt worden. Unglücklicherweise sind die Apotheker und ich über die Verteilung der uns gegebenen Ressourcen uneins, also steht mir nichts zur Verfügung, mit dem ich sie zerstören könnte!\n\nGen Nordosten liegen die Aasfelder. Die dortigen Belagerungsschmiede der Geißel bei ihren Schmieden und Fleischwagen sind so etwas wie Meister der Verwüstung.\n\nDoch zum Glück lassen sie ihre Bomben einfach so herumliegen.\n\nIch möchte, dass Ihr mir das Zeug bringt; vom Boden oder von den Schmieden selbst - ist mir egal.", sourceObjective = "Todeswache Molder in Gallgrimm möchte, dass Ihr 6 Bomben des Belagerungsschmiedes beschafft.", progress = "Man sollte doch meinen, dass sie mich ihre Seuchenverbreiter benutzen lassen würden... damit ich sie vielleicht mit irgendwas Gefährlichem beladen und die Ballisten zerstören könnte.\n\nAber nein, nein... sie meinen, dass die nur für Spezialmissionen gedacht seien.\n\nWas auch immer!", completion = "<Die Todeswache reibt sich vor Vorfreude die Hände.>\n\nAusgezeichnet. Ihr Verlust ist mein... ähhm... ist unser Gewinn!\n\nIhr hattet auf dem Weg hierher doch keine Probleme mit den Dingern, oder? Einige von denen sehen ziemlich instabil aus. Ich mag vielleicht untot sein, doch meine Existenz schätze ich allemal!", sourceObjectiveStatus = "unverified-source-field" }
quests[12231] = { id = 12231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jungen des Bärengottes", description = "Es ist möglich, dass die Furbolgs von den Grizzlyhügeln demselben Verderben unterliegen, das schon Vordrassil plagte. In letzter Zeit waren sie, nach Jahren der friedlichen Koexistenz, in einen tödlichen Stammeskrieg verwickelt.\n\nDie Schreine, die sie im Osten bewachen, sind das Zuhause von Ursocs Jungen.\n\nSollte die Verderbnis auch die Furbolgs betreffen, so ist es möglich, dass Kodian und Orsonn aufgrund ihrer Abstammung unversehrt geblieben sind.\n\nSollte dies der Fall sein, so findet sie und hört, was sie zu sagen haben.", sourceObjective = "Windseherin Grauhorn in der Burg Siegeswall möchte, dass Ihr mit Orsonn am Schrein des Grollfangs und Kodian am Schrein des Herzbluts sprecht.", completion = "Ursocs Kinder sind weise. Ihre Worte erklären viel von dem, was wir bisher gesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12232] = { id = 12232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombardiert die Ballisten", description = "Zu guter Letzt bietet sich uns die Chance, ihre Belagerungsmaschinen anzugreifen! Vermasselt es nicht.\n\nWar nur Spaß - nur ein klein wenig.\n\n{class}, nehmt Neuherdweilers Ballisten mit diesen Bomben unter Beschuss.\n\nWir werden der Königlichen Apothekervereinigung zeigen, wie es auf die altmodische Art und Weise gemacht wird - ohne Gebräue!", sourceObjective = "Todeswache Molder in Gallgrimm möchte, dass Ihr mit den Bomben des Belagerungsschmiedes 5 Ballisten von Neuherdweiler unter Beschuss nehmt.", completion = "Welch freudiger Tag!\n\nDa ich zur Erledigung des Auftrags nicht die Zeit und Mittel der Apotheker in Anspruch genommen habe, ist mir die Aufmerksamkeit des Hochexekutors sicher!\n\nIch kann nämlich um die Ecke denken - das ist meine größte Stärke. Ja, ja, Ihr hattet dabei natürlich auch ein Händchen im Spiel.\n\nHier, wenn ich Euch etwas gebe, versprecht Ihr mir dann, nichts von Eurem Zutun zu erwähnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12233] = { id = 12233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Samen aussäen", description = "Nein, nein... Behaltet sie.\n\nIhr habt doch nicht ernsthaft erwartet, dass ich sie nach all dem an mich nehme, oder?\n\nIhr macht Folgendes..." }
quests[12234] = { id = 12234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das muss ich wissen", description = "Ich muss wissen, was in Neuherdweiler los ist.\n\nIch möchte, dass Ihr ihre Tagesübersicht stehlt, damit ich genau das herausfinden kann.\n\nBegebt Euch nach Süden. Die Pläne sollten sich in der Abtei, der Kaserne und auf dem Strand befinden. Sucht und findet sie!\n\nUnd nur für den Fall, dass Ihr Euch nicht auskennen solltet. Die Kaserne ist das große Gebäude gleich neben der Schmiede.", sourceObjective = "Spionagemeisterin Repine möchte, dass Ihr die \"Tagesübersicht des Scharlachroten Ansturms: Abtei\", \"Tagesübersicht des Scharlachroten Ansturms: Kaserne\" und die \"Tagesübersicht des Scharlachroten Ansturms: Strand\" stehlt.", progress = "Wenn Ihr zu lange braucht, dann werden sich ihre Pläne ändern und wir müssen wieder von vorne anfangen.\n\nLasst Euch nicht zu viel Zeit!", completion = "Nun, worauf wartet Ihr noch, {race}? Gebt sie schon her!", sourceObjectiveStatus = "unverified-source-field" }
quests[12235] = { id = 12235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naxxramas und der Fall von Wintergarde", description = "Lord Fordragon hat bei der Pforte des Zorns einen vernichtenden Angriff gegen Arthas' Truppen eingeleitet. Als Antwort auf diesen Affront hat Arthas Naxxramas in den Kampf gegen uns geschickt. Während Kel'Thuzad sich in der schwebenden Zitadelle versteckt hält, wird Wintergarde von seinem Feldkommandanten Thel'zan belagert. Das untere Dorf ist bereits verloren und die Chance, Überlebende aus den Ruinen zu bergen, schwindet von Minute zu Minute.\n\nWir müssen schnell handeln! Meldet Euch umgehend bei Greifenkommandant Urik an der Greifenstation! Er wird Euch Flügel verleihen.\n\nVerlasst mich nun!", sourceObjective = "Sprecht mit dem Greifenkommandanten Urik an der Greifenstation in der Feste Wintergarde.", completion = "<Urik deutet auf einen Greifen.>\n\nHabt Ihr jemals schon einen von denen hier geritten? Es ist ganz einfach, {class}. Schwingt Euch einfach auf den Sattel und sagt ihm, wohin er fliegen soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[12236] = { id = 12236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursoc, der Bärengott", description = "Der Augenblick ist gekommen, {name}. Nun werden wir sehen, ob unsere Anstrengungen Früchte tragen oder nicht.\n\nNehmt diese Asche und sucht den Furbolg Tur Wutpranke, von dem Kodian Euch erzählt hat. Er hält sich in der Nähe von Ursocs Höhle auf, die Ihr nördlich des Grauschlunds findet.\n\nÜberzeugt Tur, Euch zu helfen, denn Ihr werdet alle Hilfe brauchen, die Ihr kriegen könnt.\n\nSobald Ihr den Bärengott bezwungen habt, streut diese Asche über seinen Körper.\n\nSelbst wenn seine weltliche Hülle zerstört ist, muss sein Geist gerettet werden.", sourceObjective = "Windseherin Grauhorn in Burg Siegeswall möchte, dass Ihr Tur Wutpranke in der Nähe von Ursocs Höhle findet und Ursoc mit seiner Hilfe besiegt. Streut die geläuterte Asche von Vordrassil auf Ursocs Leiche, nachdem Ihr ihn getötet habt.", completion = "<Die Druidin sieht blass aus und ihre Augen starren an Euch vorbei. Sie hat anscheinend auf Eure Rückkehr gewartet und ein Paket für Euch hingestellt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12237] = { id = 12237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug des Verteidigers von Wintergarde", description = "Mit dieser Pfeife könnt Ihr einen Greifen von Wintergarde zu Euch rufen. Steigt anschließend auf, macht Euch auf den Weg nach Südosten zu den Ruinen des Dorfs Wintergarde, jetzt Aasfelder genannt, und haltet dort nach hilflosen Dorfbewohnern von Wintergarde Ausschau. Fliegt nah an sie heran, wenn Ihr einen gesichtet habt, hebt sie mithilfe des Greifen vom Boden auf und fliegt anschließend mit dem Geretteten hierher zur Greifenstation zurück.\n\nDie Diener der Geißel sind überall in der Gegend verstreut, also müsst Ihr auf der Hut sein. Viel Glück!", sourceObjective = "Rettet 5 hilflose Dorfbewohner von Wintergarde und kehrt anschließend zum Greifenkommandanten Urik in Wintergarde zurück.", completion = "Bemerkenswerte Arbeit, {name}! Jetzt, da unsere Bürger wieder hier sind, können wir diese Festung wieder auf Vordermann bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12238] = { id = 12238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Drak'Tharons", description = "Bald wird Drak'Tharon von den verdorb'nen Untoten gereinigt und wieder ihrer ursprünglichen noblen Aufgabe unterstellt werden. Als Belohnung für deine Hilfe werd'n dir die wertvollsten Schätze der Feste zur Verfügung steh'n, Mann!\n\nSobald du ihre Spitze erreicht hast, musste mich beschwör'n, und ich führ' das Ritual durch.\n\nAber mich zu ruf'n, Mann, wird einiges kosten. Du musst das Mojo von den Überlebenden sammeln.", sourceObjective = "Drakuru möchte, dass Ihr Drakurus Elixier an seinem Kohlenbecken innerhalb Drak'Tharons benutzt. Um das Elixier dort benutzen zu können, benötigt Ihr 5 Ausdauermojos.", completion = "Wir ham' großes geleistet, Mann! Un' das is' nur der Anfang…\n\nSuch mich in Zul'Drak auf, wenn die Zeit reif is'.\n\nEs gibt 'nen Krieg zu gewinnen, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[12239] = { id = 12239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Spion in Neuherdweiler", description = "Ich habe eine meiner Spioninnen beim Scharlachroten Ansturm sitzen und möchte, dass ihr diese Tagesübersicht überbracht wird, damit sie die nächste Phase unseres Angriffes planen kann.\n\nSie wird Agentin Skully genannt und ist magisch verkleidet, um wie die Totengräberin des Ansturms auszusehen.\n\nHier, bringt Ihr dieses Schreiben und macht, was sie von Euch verlangt. Ihr findet den Friedhof gleich neben der Abtei.", sourceObjective = "Liefert die Tagesübersicht des Scharlachroten Ansturms bei Agentin Skully in Neuherdweiler ab.", progress = "<Die Agentin mustert Euch von Kopf bis Fuß und gibt Euch ein Zeichen, dass Ihr zu ihr kommen sollt.>\n\nLasst mich bloß nicht auffliegen, {class}!", completion = "Ihr habt Nachricht von der Spionagemeisterin?\n\n<Die Agentin vergewissert sich, dass niemand zusieht, und legt die Schaufel ab.>\n\nLasst mich diese Pläne einmal sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12240] = { id = 12240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mittel zum Zweck", description = "Mit der letzten Lieferung habe ich von meiner Schwester am Bollwerk ein paar Fässer mit Termiten geschickt bekommen. Sie werden bei dem, was ich mit Euch vorhabe, nützlich sein, denke ich.\n\nDie Abholzungsarbeiten bei Neuherdweiler sind uns ein Dorn im Auge, doch bisweilen haben wir es noch nicht geschafft, jemandem Zugang zu verschaffen, um ihren Vorarbeiter auszuschalten.\n\nIch denke jedoch, dass er mit Sicherheit angerannt käme, wenn Ihr diese Termiten auf seine kostbaren Holzarbeiten loslassen würdet.\n\nBereit, ihn auszuschalten, {class}?", sourceObjective = "Apothekerin Vicky Levine in Gallgrimm möchte, dass Ihr mithilfe der Termiten der LevinefamilieGroßknecht Kaleiki hervorlockt und ihn tötet.", completion = "Ich habe gewusst, dass meine Schwester uns nicht im Stich lassen würde.\n\nGut gemacht, {name}. Das Sägewerk des Scharlachroten Ansturms wird eine ganze Weile außer Betrieb sein, was die Herstellung neuer Bauwerke oder Ballisten erst einmal lahmlegt.\n\nIch danke Euch, dass Ihr mir dabei geholfen habt, meinem Familiennamen gerecht zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12241] = { id = 12241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstört den Schössling", description = "Die Taten der Furbolgs müssen rückgängig gemacht werden, {name}. Der beste aller Vorsätze zählt nicht viel, wenn das Resultat von solch starker Verderbnis durchzogen ist.\n\nDer Schössling muss zerstört werden, da er die Quelle dieses finsteren Einflusses ist. Nehmt diese Fackel und benutzt sie, um den verderbten Schössling in Flammen aufgehen zu lassen, und bringt mir dann seine Asche.\n\nEinmal durch das Feuer gereinigt, werde ich alle Macht, die ich habe, einsetzen, um den Schatten, der auf der Asche liegt, zu beseitigen. Ihr werdet sie brauchen, um Ursoc von der bösen Macht zu befreien, die ihn beherrscht.", sourceObjective = "Windseherin Grauhorn in Burg Siegeswall möchte, dass Ihr die grüne Fackel nehmt und sie benutzt, um Vordrassils Schössling zu verbrennen. Bringt Vordrassils Asche zurück zu Windseher Grauhorn.", progress = "Habt Ihr die Asche für mich, {name}?", completion = "Ich kann nichts versprechen, {name}. Aber ich werde mein Bestes geben, um sie zu reinigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12242] = { id = 12242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassils Samen", description = "Wir müssen dafür sorgen, dass Vordrassil niemals wieder wächst. Die Furbolgs müssen seine Samen eingesammelt haben.\n\nGeht nach Grauschlund in der Mitte der Grizzlyhügel und beschafft alle Samen, die Ihr finden könnt. Ich werde dafür sorgen, dass sie auf jeden Fall vernichtet werden.", sourceObjective = "Windseherin Grauhorn in Burg Siegeswall möchte, dass Ihr nach Grauschlund geht und 8 Samen von Vordrassil beschafft.", progress = "Habt Ihr Vordrassils Samen dabei, {name}?", completion = "Habt Dank, {name}. Ich werde sie dann an mich nehmen.\n\nDie verderbende Macht dieser Samen ist gefährlich. Ich muss sie umgehend zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[12243] = { id = 12243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer auf dem Wasser", description = "Ich hab' noch einen Auftrag für Euch.\n\nIch habe es geschafft, ein wenig der Seuche so zu manipulieren, dass ich daraus mein weltbekanntes brennendes Wasser zusammenbrauen konnte. Ich möchte, dass Ihr damit die Segel der Sündenbabel in Brand steckt!\n\nWerft es vom Dock aus auf die Segel. Die Deckmatrosen werden damit beschäftigt sein, das Feuer zu löschen, was Euch die Gelegenheit bietet, unter Deck zu huschen und an die Seekarten des Kapitäns heranzukommen.\n\nDas Schiff liegt im Hafen des Kreuzzüglers vor Anker, südlich von Neuherdweiler. Die Kapitänskajüte befindet sich auf dem ersten Unterdeck hinter der Treppe.", sourceObjective = "Apothekerin Vicky Levine in Gallgrimm möchte, dass Ihr mithilfe des Feuerwassers des Apothekers die Segel der Sündenbabel in Brand steckt.\n\nGeht unter Deck, während die Deckmatrosen damit beschäftigt sind, das Feuer zu löschen, und sucht nach Kapitän Shelys Seekarten.", progress = "Bitte sagt mir NICHT, dass mein Feuerwasser keine Wirkung auf ihre Segel hatte!\n\nIch hätte rein gar keine Lust, es wieder dort draußen austesten zu müssen.", completion = "Ahhahahahahahahahaha!\n\nOhne ihre Seekarten gibt es für sie kein Entrinnen mehr.\n\nSieht mir nach dem Ende des Scharlachroten Ansturms aus - gerade, als sie richtig in Fahrt kamen. Wie traurig.\n\nHeh.", sourceObjectiveStatus = "unverified-source-field" }
quests[12244] = { id = 12244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredder reparieren", description = "Hört mal, Freundchen. Wieso krempelt Ihr nicht Eure Ärmel hoch und schnappt Euch 'nen Schraubenschlüssel? Gibt viel zu tun! Diese Schredder müssen aufgemöbelt und runter zur Venturebucht geschickt werden, und das schon gestern...\n\nKein Schraubenschlüssel? Und zu was seid Ihr dann gut? Könnt dann genauso gut mit dem Rest der Blechköpfe runtergehen und mit der Horde spielen!\n\nSolang' könntet Ihr auch versuchen, 'n paar von den kaputten Schreddern hier hoch zur Reparatur zu bringen. Seid vorsichtig! Sie sind in einem ziemlich miesen Zustand.", sourceObjective = "Synipus beim Holzfällerposten Blauhimmel möchte, dass Ihr ihm 3 kaputte Schredder bringt.", completion = "<Synipus pfeift.>\n\nOh, was für 'ne Schönheit! Wir richten sie gleich wieder her!\n\nWenn Ihr nix zu tun habt, dann sprecht mit Gordun und lasst Euch runter zur Venturebucht bringen. Die brauchen da sicher 'ne helfende Hand.\n\nOh, und solange Ihr dort seid, benutzt doch diese Schlüssel an 'nem runderneuerten Schredder. Wartet, bis Ihr seht, was die Babys anrichten, wenn sie mal repariert sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[12245] = { id = 12245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade für Gefangene", description = "Wir haben noch mehr Narren für Euch, die Ihr umbringen müsst.\n\nMeine Männer berichten mir, dass einige unserer guten Bürger es geschafft haben, dem Scharlachroten Ansturm in die Hände zu fallen.\n\nDas kann so nicht angehen.\n\nGeht zurück nach Neuherdweiler und tötet Todeswache Schneider, Chefschreiber Kinnedius, Ingenieur Hindermann und Kanzler Amai.\n\nBerichten nach zu urteilen, sind sie über das gesamte Gebiet verteilt und werden in Käfigen festgehalten; doch auf sie wartet zweifellos die Folter.\n\nSprecht mit ihnen und tötet sie dann!", sourceObjective = "Spionagemeisterin Repine hat Euch gebeten, Todeswache Schneider, Chefschreiber Kinnedius, Ingenieur Hindermann und Kanzler Amai zu töten.\n\nFalls Ihr Erfolg habt, berichtet Hochexekutor Zürner in Gallgrimm davon.", completion = "Was? Ihr habt angenommen, wir würden Euch ausschicken, um sie zu retten?\n\nWarum sollten wir das denn tun, wenn sich bereits gezeigt hat, dass sie sich ohne weiteres gefangen nehmen lassen?\n\nNordend ist ein kalter Ort, junger {name}. Ich schlage vor, Ihr gewöhnt Euch dran.", sourceObjectiveStatus = "unverified-source-field" }
quests[12246] = { id = 12246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine mögliche Verbindung", description = "Die Furbolgs, die östlich von hier leben, sind aggressiver und bestialischer als die, an die wir gewöhnt sind. Unsere Streitkräfte sind mehr als einmal mit ihnen aneinandergeraten und die Überlebenden sprechen immer von einer dunklen, schleimigen Substanz, die aus ihren Körpern tropft.\n\nIhr Zustand könnte mit den Verunreinigungen zu tun haben, die wir auf Vordrassils Überresten gefunden haben.\n\nBringt mir Proben des Furbolgbluts. Ihr findet sie am Schrein des Grollfangs und am Schrein des Herzbluts, weit im Osten.", sourceObjective = "Hierophantin Thayreen bei der Ammertannhütte möchte, dass Ihr am Schrein des Grollfangs und am Schrein des Herzbluts 8 Blutproben von wahnsinnigen Furbolgs sammelt.", progress = "Habt Ihr die Blutproben sammeln können, {name}?", completion = "Die Verderbnis in diesem Blut gleicht der in dem Schleim. Ich habe kein gutes Gefühl bei der Sache.", sourceObjectiveStatus = "unverified-source-field" }
quests[12247] = { id = 12247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinder von Ursoc", description = "Die Furbolgs der Grizzlyhügel sind von einer Art Verderbnis befallen, so viel steht fest. Nun ist ein Stammeskrieg zwischen ihnen ausgebrochen, nachdem sie jahrelang friedlich miteinander gelebt hatten.\n\nWas wir noch herausfinden müssen, ist, ob die Bären, die sie als Götter verehren, auch der Verderbnis anheim gefallen sind.\n\nUrsocs zwei Kinder, Orsonn und Kodian, halten sich im Schrein des Herzensblutes und des Grollfangs auf, süd- und südöstlich von Grauschlund.\n\nSeht nach, ob sie mit Euch über das, was dort geschehen ist, sprechen werden.", sourceObjective = "Hierophantin Thayreen bei der Ammertannhütte möchte, dass Ihr mit Orsonn im Schrein des Grollfangs und mit Kodian im Schrein des Herzensblutes sprecht.", completion = "Ursocs Kinder sind weise. Ihre Worte erklären einiges von dem, was wir gesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12248] = { id = 12248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassils Schössling", description = "Die Druiden von einst scheinen guten Grund gehabt zu haben, Vordrassil zu zerstören. Wir können nicht zulassen, dass die Furbolgs ihn wieder gedeihen lassen.\n\nAuf der anderen Seite hängt die Rettung von Ursocs Geist von der Magie ab, die in diesem Schössling steckt.\n\nNehmt diese Fackel und steckt mit ihrer Hilfe den Baum in Brand. Er befindet sich in der Mitte von Grauschlund im Inneren von Vordrassils altem Baumstamm. Bringt mir die Asche von Vordrassil. Ich hoffe, dass, sobald er vom Feuer gereinigt wurde, wir mithilfe seiner Magie Ursocs Geist von seiner Dunkelheit läutern können.", sourceObjective = "Hierophantin Thayreen in der Ammertannhütte möchte, dass Ihr mithilfe der grünen Fackel Vordrassils Schössling anzündet und ihr die daraus entstehende Asche von Vordrassil bringt.", progress = "Habt Ihr mir die Asche gebracht, {name}?", completion = "Ja! Vordrassils Magie ist erhalten geblieben und steckt noch immer in dieser Asche. Vielleicht gibt es doch noch Hoffnung für Ursoc.", sourceObjectiveStatus = "unverified-source-field" }
quests[12249] = { id = 12249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursoc, der Bärengott", description = "Es ist Zeit, {name}. Nehmt diese Asche und sucht nach dem Furbolg, von dem Kodian gesprochen hat. Wenn er sich auf die Suche nach Ursoc gemacht hat, dann wird er in der Nähe seines Baus nördlich von Grauschlund sein.\n\nIhr werdet seine Hilfe benötigen. Alleine werdet Ihr Ursoc nicht besiegen können.\n\nBenutzt die Asche, um seinen Geist zu läutern, sobald Ihr Ursoc besiegt habt. Erst dann werden wir wissen, ob unsere Mühen umsonst waren oder nicht.", sourceObjective = "Hierophantin Thayreen bei der Ammertannhütte möchte, dass Ihr Tur Wutpranke in der Nähe von Ursocs Höhle aufsucht und mit seiner Hilfe Ursoc besiegt. Streut anschließend die geläuterte Asche von Vordrassil auf Ursocs Leiche.", completion = "<Die Druidin sieht blass aus und ihre Augen starren an Euch vorbei. Sie hat anscheinend auf Eure Rückkehr gewartet und ein Paket für Euch hingestellt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12250] = { id = 12250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassils Samen", description = "Wir können nicht zulassen, dass Vordrassil wieder wächst. Wenn die Furbolgs es einmal geschafft haben, ihn wachsen zu lassen, dann können sie es wieder tun.\n\nGeht zum Grauschlund im Zentrum der Grizzlyhügel und besorgt Vordrassils Samen. Ich werde dann sicherstellen, dass sie ein für alle Mal verschwinden.", sourceObjective = "Hierophantin Thayreen in der Ammertannhütte will, dass Ihr zum Grauschlund geht und 8 Samen von Vordrassil besorgt.", progress = "Habt Ihr die Samen, {name}?", completion = "Danke, {name}. Ich werde sie an mich nehmen.\n\nDie verderbende Macht dieser Samen ist äußerst gefährlich. Ich muss sie sofort zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[12251] = { id = 12251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zum Oberkommandanten zurück", description = "{name}, Ihr müsst umgehend zum Hochkommandanten Halford Wyrmbann zurückkehren. Lasst ihn wissen, dass unsere Mission ein voller Erfolg war und dass die wenigen verbliebenen Dorfbewohner, die gerettet wurden, wieder bei der Arbeit sind.", sourceObjective = "Sprecht mit Hochkommandant Halford Wyrmbann in Wintergarde in der Drachenöde.", completion = "<Halford salutiert vor Euch.>\n\nDas Stadtvolk ist wieder bei der Arbeit? Jetzt schon? Ausgezeichnet, Soldat! Wir werden diese Stadt im Handumdrehen wieder aufgebaut und befestigt haben. Nicht mehr lange und unsere Truppen werden einsatzbereit sein und Lord Fordragon bei seinem Kampf an der Pforte des Zorns zur Seite stehen.\n\nIch bin natürlich etwas zu voreilig - bevor wir nämlich überhaupt erst daran denken können, Euch zu Bolvars Hilfe zu schicken, muss hier noch einiges getan werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12252] = { id = 12252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foltert den Folterer", description = "Genug! Ich möchte, dass Ihr den Qualen meines Volkes ein Ende setzt!\n\nDer Folterer des Scharlachroten Ansturms, Alphonse, erzwingt auf die blutigste Art und Weise Informationen von allen, die von diesen Scheusalen gefangen genommen werden! Ich muss wissen, was sie wissen.\n\nAus gewissen Quellen habe ich erfahren, dass er sich im Keller ihrer Kaserne, die sich gleich neben der Schmiede befindet, eingerichtet hat.\n\nIch werde Euch mein eigenes Brandeisen ausleihen, damit die Arbeit auch richtig erledigt wird.\n\nFindet ihn und beschafft Euch die Informationen.", sourceObjective = "Hochexekutor Zürner in Gallgrimm möchte, dass Ihr Folterer Alphonse fünfmal mit dem Brandeisen bearbeitet und die Informationen aus ihm herausquetscht. Anschließend sollt Ihr ihn töten.", completion = "Sie wussten das alles? Und wer zum Teufel ist dieser Großadmiral Westwind, den er erwähnt hat?!\n\n<Der Hochexekutor murmelt vor sich hin und meint, dass er Überraschungen nicht ausstehen kann.>\n\nGut zu wissen. Besser das, als nur Vermutungen anzustellen. Ich hoffe, dass Ihr Euer... ähm, ich meine, dass Ihr mein Mal hinterlassen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12253] = { id = 12253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung vom Marktplatz", description = "Gleich diesen Weg entlang befindet sich der Dorfplatz von Wintergarde. Einst war dies ein geschäftiger Ort für die Bürger von Wintergarde, doch nun ist aus ihm ein Kampfschauplatz geworden und wimmelt nur so von blutrünstigen Spuken, die sich um jeden Preis an den Lebenden rächen wollen.\n\nIn den Gebäuden um den Platz herum befinden sich gefangene Dorfbewohner, die unbedingt befreit werden müssen! Dies mag jetzt vielleicht etwas viel verlangt sein, {name}, doch Ihr seid <der einzige Soldat, den/die einzige Soldatin> die; ich entbehren kann. Befreit unsere Leute. Folgt diesem Pfad zum Dorfplatz, geht zu den Häusern und tötet alles, was sich Euch in den Weg stellt! Kehrt wieder zu mir zurück, falls Ihr überleben solltet.", sourceObjective = "Hochkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 6 gefangene Dorfbewohner von Wintergarde befreit.", completion = "<Halford spricht ein Gebet für die Verstorbenen.>\n\nIhr verrichtet des Lichtes Arbeit, {name}.\n\nIch fürchte, dass unsere Arbeit gerade erst begonnen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12254] = { id = 12254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Gebet", description = "Diese Pläne lassen darauf schließen, dass etwas kurz bevorsteht.\n\nDoch zuerst ist da noch die Sache mit diesem seltsamen Schutz, über den die Truppen des Ansturms verfügen. Wenn Gallgrimm ein für alle Mal mit ihnen abrechnen will, dann müssen wir den Verantwortlichen dafür finden und ihn ausschalten.\n\nIch habe bemerkt, dass der Bischof in der Kapelle gegenüber dem Sägewerk auf der anderen Seite von Neuherdweiler häufiger als sonst den Truppen seinen Segen erteilt. Tötet ihn und nehmt ihm sein Gebetsbuch ab.\n\nVielleicht wird es uns einen Hinweis geben.", sourceObjective = "Agentin Skully in Neuherdweiler möchte, dass Ihr das Gebetsbuch von Bischof Straß besorgt.", progress = "Ihr habt das Gebetsbuch des Bischofs? Habt Ihr darin auch irgendetwas Ungewöhnliches gefunden?", completion = "Ihr meint also, dass auf der letzten Seite des Buches ein neuer Segen geschrieben steht?\n\n<Die Agentin blickt Euch über die Schulter, als Ihr die letzte Seite aufschlagt.>\n\nVerdammt nochmal! Das ist die Handschrift des Hochabtes! Ich würde Euer Leben darauf verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12255] = { id = 12255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Than von Voldrune", description = "Nun, da Ihr die flammenerfüllten Talismane in Händen haltet und die Verteidigung von Voldrune geschwächt habt, können wir einen Schlag gegen ihren Anführer ausführen, den Than Torvald Eriksson.\n\nSein Lieblingsreittier ist ein nicht zu bändigender Protodrache, den er Flammenbringer nennt. Er wird im westlichen Teil von Voldrune in Ketten gehalten, doch mithilfe der Talismane solltet Ihr ihn lange genug beherrschen können, um ihn gegen den Than einzusetzen.\n\nDer Than hält sich irgendwo oben auf den Türmen von Voldrune auf. Sucht dort nach ihm, sobald Ihr Flammenbringer unter Eure Kontrolle gebracht habt, und zeigt keine Gnade.", sourceObjective = "Besiegt mithilfe von Flammenbringer den Than Torvald Eriksson und meldet Euch anschließend bei Förster Drach bei der Ammertannhütte.", completion = "Gute Arbeit, {name}. Ich bezweifle, dass irgendeiner der Förster sich an dem Protodrachen hätte versuchen wollen, doch wir konnten es einfach nicht zulassen, dass die Drachenschinder eine Basis in den Grizzlyhügeln errichten. Wenn es mit der Horde nur auch so leicht wäre...", sourceObjectiveStatus = "unverified-source-field" }
quests[12256] = { id = 12256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnis der Flammenbinder", description = "Während die feige Allianz unsere Stellungen angreift, bereiten sich die Vrykul der Drachenschinder im Außenposten Voldrune gen Südosten auf den Krieg vor. Die Vrykul sind bei Weitem nicht der stärkste Feind, dem wir uns hier gegenübersehen, doch wir müssen sie aus dem Weg räumen, bevor sie eine wirkliche Bedrohung für uns darstellen.\n\nDen stärksten ihrer Krieger ist es gestattet, auf schlecht trainierten Protodrachen in die Schlacht zu reiten. Um die Bestien zu kontrollieren, erschaffen die Flammenbinder mächtige Talismane. Ihr werdet sie töten und die Talismane an Euch bringen müssen, damit unser Plan funktioniert.", sourceObjective = "Bringt 3 flammenerfüllte Talismane zu Unteroffizier Nazgrim in Burg Siegeswall.", progress = "Habt Ihr diese Talismane dabei?", completion = "Die Macht der Talismane bewirkt, dass die Drachen keine andere Wahl haben, als Euren Befehlen zu gehorchen. Das Schicksal des Thans ist besiegelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12257] = { id = 12257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Demonstration der Stärke", description = "Das Vrykuldorf Voldrune im Südosten bereitet sich auf den Krieg vor. Der Than von Voldrune kann keine große Armee in die Schlacht führen, aber durch unsere reduzierte Truppenstärke sind wir dennoch in Gefahr.\n\nWir können nicht riskieren, einem Angriff ausgesetzt zu werden, also müssen wir die Initiative ergreifen. Wenn Ihr <ein wahrer/eine wahre:c> {class} der Horde seid, werdet Ihr auf eine Chance brennen, Eure Stärke zu demonstrieren.\n\nMäht die Huscarls nieder und beweist diesem Drachenschinderklan, dass mit der Horde nicht zu spaßen ist!", sourceObjective = "Tötet 12 Huscarls der Drachenschinder und kehrt zu Unteroffizier Nazgrim am Siegeswall zurück.", completion = "Ihr habt getan, worum ich Euch gebeten habe. Jetzt sind die Drachenschinder in der Defensive und es ist bald an der Zeit, sich um ihren Anführer zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[12258] = { id = 12258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Toten", description = "Der Dorfplatz am Ende dieses Weges wimmelt nur so von untoten Bürgern von Wintergarde! Unsere eigene Krypta versorgt die Geißel mit einer schier endlosen Zahl Krieger, die sie dann auf uns hetzen kann. Zeigt ihnen jedoch keine Gnade, {name}. Einst waren sie Sterbliche wie wir, des Mitgefühls und Denkens fähig, doch jetzt sind aus ihnen wütende Untote geworden, die nur ein Ziel kennen: unsere völlige Zerstörung.\n\nGeht zum Dorfplatz, wenn Ihr den Mut dazu habt, und befördert die rachsüchtigen Spuke wieder zu ihrem Schöpfer zurück. Sorgt dafür, dass sie in Frieden ruhen können.", sourceObjective = "Kommandantin Lynore Windstreich in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 15 rachsüchtige Spuke tötet.", completion = "Vielleicht werden sie jetzt in Frieden ruhen können, da es ihren Geistern nicht mehr verwehrt ist, zum Licht emporzusteigen.\n\nMeine Gedanken und Gebete gehen nun an Lord Fordragon und unsere Streitkräfte an der Pforte des Zorns. Wir müssen hier ausharren, auch wenn ihnen das vielleicht nur genug Zeit verschaffen wird, um den Lichkönig zu besiegen. Wintergarde darf nicht fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12259] = { id = 12259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Than von Voldrune", description = "Mit den flammenerfüllten Talismanen können wir den Than endlich herausfordern!\n\nSein Lieblingsreittier ist ein wilder Protodrache namens Flammenbringer. Er wird im westlichen Teil Voldrunes in Fesseln gehalten, aber mit der Kraft der Talismane solltet Ihr ihn Eurem Willen unterwerfen und gegen den Than einsetzen können.\n\nSobald Ihr Flammenbringer unter Kontrolle gebracht habt, sucht auf den Turmspitzen von Voldrune nach dem Than, um ihn mit Flammenbringer zu erledigen.", sourceObjective = "Besiegt mithilfe von Flammenbringer Than Torvald Eriksson und meldet Euch anschließend bei Unteroffizier Nazgrim in Burg Siegeswall.", completion = "Die wenigen verbliebenen Drachenschinder wagen es nicht, sich uns nach dem Kampf mit dem Than entgegenzustellen. Kein Erbarmen mit unseren Feinden - das ist der Weg der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[12260] = { id = 12260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die perfekte Heuchelei", description = "Womöglich fragt Ihr Euch, wie ich diese Gestalt aufrechterhalten kann... Ich verwende einen magischen Spiegel, den mir die Spionagemeisterin geliehen hat.\n\nEr hat zwar nur eine gewisse Menge an Energie, doch ich denke, dass genug für uns beide da ist. Hier, nehmt ihn. Ich möchte, dass Ihr Euch mit seiner Hilfe als Rabenpriester des Ansturms ausgebt.\n\nMacht schnell... ich weiß nicht, wie lange ich noch so bezaubernd aussehen werde, wenn Ihr den Spiegel habt.\n\nIhr müsst wissen, dass Eure Verkleidung nicht sofort perfekt sein wird. Idiotensicher ist sie erst dann, wenn ich eine Chance hatte, Euch zu helfen.", sourceObjective = "Agentin Skully in Neuherdweiler möchte, dass Ihr das Abbild eines Rabenpriesters des Ansturms stehlt. Bringt den magischen Spiegel der Banshee wieder zurück, wenn Ihr das getan habt.", progress = "Bitte sagt mir, dass Ihr den Spiegel nicht zerbrochen habt!", completion = "Nicht schlecht, Jägerin. Nun, da das Abbild des Priesters im Spiegel gefangen ist, hätte ich noch eine andere Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12261] = { id = 12261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Ausweg", description = "Sie beziehen ihre Macht aus den Knochen meiner toten Brüder...\n\nFür den Kult habe ich nichts übrig, aber ihre Dreistigkeit verblüfft mich. Es wird keine Gnade für sie geben... ich würde ihnen ohnehin keine gewähren, so oder so.\n\nStellt sicher, dass ihnen kein Fluchtweg bleibt, wenn das Schlachten beginnt. Stellt eine zerstörerische Barriere am Ende des Pfades auf, der aus dem Obsidiandrachenschrein hinausführt; dort, wo die Straße in Schnee übergeht. Schützt die Barriere, bis sie vollständig aufgeladen ist.", sourceObjective = "Stellt eine zerstörerische Barriere am Ende des Pfades auf, der aus dem Obsidiandrachenschrein hinausführt; dort, wo die Straße in Schnee übergeht. Schützt die Barriere, bis sie vollständig aufgeladen ist und kehrt dann zu Serinar zurück.", completion = "Exzellent. Sobald sie in Panik fliehen, wird die Barriere dort bereit sein, um ihnen einen freundlichen Abschied zu bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12262] = { id = 12262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und niemand, der Euch retten wird...", description = "Niemand wird verschont. \n\nDort draußen besudelt dieser Nekrolythenabschaum und seine Skelettdiener mein Land mit seiner Anwesenheit. Schlachtet sie ab, alle.", sourceObjective = "Tötet außerhalb des Obsidiandrachenschreins 6 Nekrolythen der Brennenden Tiefen und 10 glimmende Skelette. Kehrt zu Serinar zurück, sobald Eure Aufgabe abgeschlossen ist.", completion = "Haben sie um ihre jämmerlichen Leben gebettelt? Schwächlinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12263] = { id = 12263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur die besten Absichten", description = "Der Kult der Verdammten ist nicht nur hier, um die Macht aus toten Drachen zu extrahieren. Ich hege einen Verdacht, was ihre Absichten betrifft. Aber ich brauche Euch, um ihn zu bestätigen.\n\nIch werde Euch das Aussehen dieses toten Nekrolythen verleihen. Dringt in das Innerste der Höhle vor und überprüft ihre Gründe, diesen geheiligten Ort heimzusuchen. Ich werde alles durch Eure Augen beobachten. \n\nSeid vorsichtig, {name}. Die Illusion ist empfindlich, erleidet Ihr Schaden wird sie wahrscheinlich zerbrechen.", sourceObjective = "Wartet, bis Serinar Euch in die Verkleidung eines Nekrolythen der Brennenden Tiefen gehüllt hat. Dringt in die Tiefen des Schlundes von Neltharion vor, um aufzudecken, was den Kult der Verdammten hierher lockt. Kehrt mit Details ihres Vorhabens zu Serinar zurück.", completion = "Wir sind der schwarze Drachenschwarm. Seit tausenden von Jahren haben wir Chaos und Verwüstung auf Azeroth verbreitet. Der Kult der Verdammten verehrt den Tod - was sie so lieben werden wir ihnen mit Freuden servieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12264] = { id = 12264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ausmerzen der Verdammten", description = "Die Tiefen der Höhle wimmelten nur so von den Scheusalen der Kultisten. Es gibt nur eine Art, mit solchen Kreaturen fertigzuwerden... Ihr wisst, was zu tun ist.", sourceObjective = "Tötet in Neltharions Schlund 3 Nekromanten der Brennenden Tiefen, 6 glimmende Konstrukte und 6 glimmende Spuke. Kehrt dann zu Serinar zurück.", completion = "Ihre Schreie zu hören... zuzusehen, wie das letzte Quäntchen Leben aus ihren erbärmlichen Körpern sickert... so erfrischend, nicht wahr?\n\nIch liebe es.", sourceObjectiveStatus = "unverified-source-field" }
quests[12265] = { id = 12265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schändung der Entweiher", description = "In den Runen, die wir auf dem Weg in die Höhle entdeckt haben, habe ich eine große Ansammlung von Magie gespürt. Mit Spielereien, wie ihnen die Magie zu entziehen, brauchen wir uns nicht abzugeben... zumeist ist die direkte Lösung die Effektivste.\n\nZerstört die Runen... löscht sie aus und stellt sicher, dass der Kult zu der Macht, die er hier angesammelt hat, keinen Zugriff hat.", sourceObjective = "Findet 8 nekromantische Runen, die auf den Boden von Neltharions Schlund gezeichnet wurden und löscht sie aus. Kehrt zu Serinar zurück, sobald die Aufgabe abgeschlossen ist.", completion = "Gut. Es gibt mehr zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[12266] = { id = 12266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kunde der Zerstörung", description = "Ihr könnt nun gehen, {race}.\n\nSagt Yntrige, sie hat ein üppiges Schlachtfest verpasst.", sourceObjective = "Kehrt zum Wyrmruhtempel zurück und lasst Yntrige wissen, dass Serinars Aufgabe abgeschlossen ist.", completion = "Oh, Ihr seid es.\n\nIch hatte gehofft, dass Serinar einfach zurückkehren würde, sobald die Aufgabe erledigt gewesen wäre... Ich nehme mal an, dass er irgendwas gefunden hat, das er töten muss. Er verpasst eine wunderbar chaotische Schlacht!\n\nSeid Ihr noch immer da? Ich bin mit Euch fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[12267] = { id = 12267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Flamme", description = "Die Reihen des Kults sind dünner geworden, ein Teil ihrer Macht ist vergangen - es ist Zeit, gegen die Quelle der Verderbnis vorzurücken.\n\nRothin der Verfallende belebt im hinteren Teil der Höhle schwarze Drachen als Magmawyrms wieder. Geht zur Beschwörungskammer und läutert die verbliebenen Knochen auf die einzige Art und Weise, wie man sicherstellen kann, dass niemand je wieder mit ihnen herumspielen wird... mit Feuer.\n\nDie Knochen zu verbrennen wird mit Sicherheit Rothins Aufmerksamkeit erregen - und wenn dem so sein sollte, dann kümmert Euch auch darum, dass er vernichtet wird.\n\nIn der Phiole sollte sich genug magische Kraft befinden, um die Aufgabe zu erledigen.", sourceObjective = "Äschert mit Neltharions Flamme die Beschwörungskammer im hinteren Teil von Neltharions Schlund ein. Tötet Rothin den Verfallenen, nachdem Ihr seine Aufmerksamkeit auf Euch gezogen habt, und kehrt anschließend zu Serinar am Eingang der Höhle zurück.", completion = "Den Knochen meines Schwarms wurde diese Besudelung erspart. Ihr habt mir gut gedient und sollt dafür angemessen entlohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12268] = { id = 12268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelteile", description = "Bah! Das Ding ist ein einziges Durcheinander!\n\nGoblinische Ingenieurskunst lässt 'ne Menge zu wünschen übrig, das könnt Ihr mir glauben. Schaut Euch das hier nur an! Ein Wunder, dass es überhaupt jemals funktioniert hat.\n\nHelft mir mal, ja? Um dies auch nur ansatzweise zum Laufen zu bringen, muss ich diverse Zahnräder, Winkel und Federn ersetzen. Ihr solltet keine Probleme haben, sie in der Nähe des Sägewerks zu finden.", sourceObjective = "Pipthwak beim Holzfällerposten Blauhimmel möchte, dass Ihr ihm 4 gefalzte Zahnräder, 3 gekerbte Winkel und 2 Hochspannungsfedern bringt.", progress = "Habt Ihr diese Ersatzteile für mich, {class}?", completion = "In der Tat. Nun sollte es hinhauen...\n\nSo, bitte. Ein weiterer Schredder bereit für den Kampf. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12269] = { id = 12269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht in unserer Mine", description = "Wir wurden von dieser verdammten Nekropole völlig überrumpelt! Durch den Überfall haben wir auch die Minen von Wintergarde an den Feind verloren. Und was noch viel schlimmer ist: Kel'Thuzads Akolythen haben die toten Bergarbeiter in Diener der Geißel verwandelt und benutzen sie, um ihre Belagerungsingenieure mit Rohstoffen aus unserer Mine zu versorgen!\n\nIhre Rohstoffquelle muss zum Erliegen kommen und unsere verlorenen Brüder wieder ihre Ruhe finden.\n\nGeht nach Nordosten zu den Minen von Wintergarde im Bereich der Aasfelder und vernichtet die auferstandenen Bergarbeiter. Bringt ihre Ausweise wieder zu mir zurück, damit ich sie als verstorben in unser Register aufnehmen kann.", sourceObjective = "Hochlord Leoric von Zeldig in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 10 Bergarbeiterausweise von Wintergarde beschafft.", progress = "Habt Ihr ihre Ausweise dabei?", completion = "<Leoric nimmt Euch die Ausweise ab.>\n\nIch werde die hier unserem Buchhalter geben und den Familien der Bergarbeiter die schlimmen Neuigkeiten überbringen.\n\nEs gibt noch immer viel zu tun, wenn wir hier und letztendlich an der Pforte des Zorns die Oberhand gewinnen wollen. Lord Fordragon ist auf uns angewiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12270] = { id = 12270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreddert die Allianz", description = "Sperrt die Ohren auf, {class}: Ich brauche diese Schredder! Und genauso wichtig: Ich muss sie von der Allianz fernhalten!\n\nSie haben die Schredder rundum erneuert und setzen sie nun gegen unsere Brüder in der Venturebucht ein. Nun werden wir sie ihre eigene Medizin schmecken lassen!\n\nWenn Ihr einen Schredder da draußen seht, dann schnappt ihn Euch! Wenn Ihr dabei irgendwelchen Allianzlern über den Weg lauft, bringt sie um und schnappt Euch dann den Schredder! Sobald Ihr einen habt, bringt ihn zurück zu mir und wir machen uns an die Arbeit.\n\nWeggetreten!", sourceObjective = "Grekk im Holzfällerlager Blauhimmel möchte, dass Ihr 3 Schredder besorgt und diesen zu ihm zurückkehrt.", completion = "Gute Arbeit, Soldat!\n\nNun nehmt diesen Schlüssel und begebt Euch runter zur Venturebucht. Verwendet einen der runderneuerten Schredder, um Chaos unter unseren Feinden zu verbreiten.\n\nAch ja, wendet Euch an Darrok, wenn Ihr die Abkürzung nehmen wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12271] = { id = 12271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rute des Zwangs", description = "Ein Stab fällt aus Alphonses toter Hand. Er ist mit pulsierenden magischen Runen versehen.\n\nHat er damit seine Geständnisse bekommen?\n\nDer Hochexekutor sollte sich das besser einmal ansehen.", sourceObjective = "Liefert den Stab des Folterers bei Hochexekutor Zürner in Gallgrimm ab.", progress = "Habt Ihr diesen Stab dem Folterer abgenommen?", completion = "LeCraft hatte ihn bei sich, meint Ihr? Das ergibt Sinn.\n\nIch habe so etwas früher schon einmal gesehen, als ich noch jünger war - zu der Zeit, als Lordaeron noch bestand und ich als Folterer in den Diensten des Königs Terenas stand. Man nennt es einen Stab des Zwangs.\n\n<Der Hochexekutor ringt die Hände in hämischer Vorfreude.>\n\nIch habe eine Idee, wie wir ihn uns zunutze machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12272] = { id = 12272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das blutende Erz", description = "Stunden vor der Invasion durch Naxxramas stolperte einer der Bergarbeiter über ein dunkles Erz, aus dem eine zähe Flüssigkeit tropfte. In dem Chaos, das bei der Evakuierung der Mine herrschte, verloren wir jedoch die aus der seltsamen Ader herausgehauenen Proben. Nun untersucht die Geißel das Erz, um herauszufinden, wie sie es in ihren todbringenden Maschinen verwenden können.\n\nIhr müsst zurück zur Mine von Wintergarde gehen, die nordöstlich von hier in den Aasfeldern gelegen ist, und in Besitz dieses seltsamen Erzes gelangen. Die Sache ist für den Erfolg unserer Mission unerlässlich!", sourceObjective = "Belagerungsingenieur Viertelblitz in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 10 Proben des seltsamen Erzes aus der Mine von Wintergarde beschafft.", progress = "Habt Ihr die Proben des seltsamen Erzes mitgebracht?", completion = "Vielleicht ist dies der Moment, der Augenblick an dem sich die Dinge gegen die Geißel wenden werden. Ihr habt Euch als Held der Allianz erwiesen - zumindest in meinen Augen, {name}.\n\nWenn Ihr nun so freundlich sein könntet und mir etwas Freiraum ließet. Ich werde etwas mehr Zeit benötigen, um dieses Erz zu untersuchen und Unreinheiten und Schwächen zu entfernen.\n\nWeiter an die Arbeit, Verbündeter. Ich werde mich bei Euch melden, sobald ich Neues habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[12273] = { id = 12273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verleumdung", description = "Es ist Zeit, dass wir die Streitkräfte des Scharlachroten Ansturms vollkommen demoralisieren!\n\nIch möchte, dass Ihr diesen Stab nehmt und mit ihm vier ihrer Anführer bezaubert: Kommandant Jordan im oberen Stockwerk der Kaserne, Kanonierführer Zierhut auf der südöstlichen Rampe am Strand, Schmied Gutmann in der Schmiede und Stallmeister Mercer bei den Ställen.\n\nBeherrscht sie mithilfe des Stabes, lasst sie den Scharlachroten Ansturm verleumden und tötet sie anschließend!", sourceObjective = "Hochexekutor Zürner in Gallgrimm hat Euch damit beauftragt, den Stab des Zwangs auf Kommandant Jordan, Kanonierführer Zierhut, Schmied Gutmann und Stallmeister Mercer anzuwenden.\n\nTötet sie, sobald Ihr den Stab verwendet habt, um ihnen als letzte Worte die Verleumdung des Scharlachroten Ansturms abzuverlangen.", completion = "<Ihr meint, ein flüchtiges Lächeln über Zürners Gesicht huschen zu sehen.>\n\nIhr seid nun offiziell mein Lieblingshexenmeister, {name}. Falls Ihr Lust dazu habt, dann solltet Ihr es vielleicht in Erwägung ziehen, ein Offizier der Hand der Rache zu werden.\n\nIhr würdet als Todeswache anfangen und ich meine, dass Ihr nach ein paar Jahrzehnten das Zeug zum Juniorexekutor hättet!\n\nNein? Nun ja, übereilen wollen wir es ja nicht... Lasst Euch Zeit und denkt einmal darüber nach.", sourceObjectiveStatus = "unverified-source-field" }
quests[12274] = { id = 12274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Ungnade fallen", description = "Wir müssen noch mehr vom Hochabt erfahren. Nun, da uns das Gesicht eines Rabenpriesters zur Verfügung steht, können wir Euch nahe genug an ihn heranbringen, damit Ihr mit ihm sprechen könnt.\n\nLeider müssen wir ihn zuerst von seinen Leibwächtern trennen, ansonsten werdet Ihr nie etwas aus ihm herausbekommen.\n\n<Die Agentin stützt sich auf ihre Schaufel und scheint nachzudenken.>\n\nIch denke, ich hab's! Geht die Abtei hinauf und läutet die Glocke, während Ihr verkleidet seid. Daraufhin sollten die Leibwächter des Abtes angerannt kommen, worauf Ihr hinuntergehen und mit ihm sprechen könnt.", sourceObjective = "Agentin Skully in Neuherdweiler möchte, dass Ihr die Glocke der Abtei läutet und anschließend vom Hochabt die benötigten Informationen beschafft.", completion = "Was zum Teufel ist hier los?!\n\nEr ist von alleine gesprungen? Seid Ihr Euch sicher, dass Ihr ihn nicht gestoßen habt?\n\n<Die Agentin blickt Euch skeptisch an.>\n\nGut. Offensichtlich wird hier mehr gespielt, als wir zuerst dachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12275] = { id = 12275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sprenggnom", description = "Viertelblitz hat vor Kurzem einen meiner Spezialisten angefordert, um eine Aufklärungsmission in den Minen von Wintergarde durchführen zu können; also habe ich ihm Schleicha geschickt, meinen Sprengmeister. Dummerweise dachte ich, dass er die Grube der Verdammnis nach abgeschlossener Mission hätte zuschütten können, um uns damit einen weiteren Sieg über die Geißel zu bescheren.\n\nNun ist schon ein ganzer Tag vergangen und Schleicha ist noch immer nicht zurück. Ich will wissen, was los ist! Sprecht mit Belagerungsingenieur Viertelblitz und findet meinen vermissten Agenten!", sourceObjective = "Sprecht mit Belagerungsingenieur Viertelblitz in der Feste Wintergarde in der Drachenöde.", completion = "Ich hab' so ein schlechtes Gefühl deswegen, {class}. Ich fürchte, dass ich in meiner Eile, an das seltsame Erz aus der Mine von Wintergarde heranzukommen, Agent Schleicha womöglich zum Tode verurteilt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[12276] = { id = 12276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Schleicha", description = "Ich hab zwar noch nichts von Schleicha gehört und weiß auch nicht, welches Schicksal ihn ereilt hat, doch vielleicht kann ich dabei helfen, ihn zu finden.\n\n<Viertelblitz hält ein kleines mechanisches Spielzeug in die Höhe.>\n\nDas ist kein Spielzeug, {class}. Tatsächlich handelt es sich hier um meine neueste mechanische Errungenschaft. Sie ist nur dafür da, um das zu finden, was verloren gegangen ist. Die Umstände sind zwar nicht die besten, doch die Maschine ist Eure beste Chance, Schleicha zu finden.\n\nStellt den Roboter neben mir auf den Boden, sobald Ihr mit der Suche beginnen wollt.", sourceObjective = "Sucht und findet Schleicha den Sprenggnom in den Minen von Wintergarde. Holt Euch Viertelblitz' Zielsuchroboter zu Hilfe, wenn Ihr die Minen nicht finden könnt.\n\nBereitgestellter Gegenstand:", completion = "<Schleichas leblose Hand umklammert einen Zettel.>\n\nSie sind hinter mir her. Kein Ausweg. Habe mich versteckt, aber sie wissen, dass ich hier bin. Bald werden sie mich finden.\n\nDie Bergarbeiter schürfen ununterbrochen nach dem seltsamen Erz, mit dem die Kriegsmaschinen der Geißel betrieben werden. Es gibt viel Gerede. Die Sprache des Todes verwirrt mich, doch ich konnte ein paar häufig verwendete Laute und Sätze identifizieren. Das Wort \"Yogg-Saron\" wird dabei mit einem verachtenden Tonfall ausgesprochen, worauf gewöhnlich laute Wutausbrüche folgen. Sie nennen das Erz \"Saronit\". Und das bedeutet?", sourceObjectiveStatus = "unverified-source-field" }
quests[12277] = { id = 12277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlasst nichts dem Zufall", description = "Lest weiter, wenn Ihr guten Herzens und reinen Gewissens seid.\n\nIn dieser Mine ruht in der Nähe des Schafotts des Vorarbeiters eine ordentliche Ladung Dynamit. Geht hin, nehmt Euch mehrere Stangen Sprengstoff und schlagt Euch zum Eingang der Mine durch. Platziert das Dynamit und sprengt den Eingang in die Luft, sobald Ihr dort angekommen seid. Vergesst nicht, dass es sowohl auf der oberen als auch der unteren Ebene einen Eingang zu den Minen von Wintergarde zu sprengen gibt.\n\nIhr dürft nichts dem Zufall überlassen. Das Böse dort darf niemals freigelassen werden. Möge das Licht Euch den Weg weisen.", sourceObjective = "Beschafft eine Minenbombe von Wintergarde und verwendet sie, um den oberen und unteren Minenschacht von Wintergarde zu sprengen. Erstattet Belagerungsingenieur Viertelblitz bei der Feste Wintergarde in Drachenöde Bericht, sobald Ihr die Aufgabe erfüllt habt.", completion = "Sein Tod soll nicht umsonst gewesen sein, mein Freund. Die Informationen, für die Schleicha sein Leben gelassen hat, werden Verwendung finden, um den Lichkönig zu bezwingen. Ich verspreche Euch, dass wir das in Ordnung bringen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12278] = { id = 12278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bier des Monats e.V.", description = "Mitgliedschaft hat ihre Vorteile. Als Mitglied des \"Bier des Monats e.V.\" weiß man einfach immer, wo es das beliebteste und beste Bier gibt.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", sourceObjective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", progress = "Habt Ihr Euren Antrag ausgefüllt?", completion = "Euer Papierkram sieht in Ordnung aus. Willkommen im Verein, {name}!\n\nStellt Euch schon mal darauf ein, zu Beginn jedes Monats Post von uns zu erhalten. Schaut doch mal vorbei, wenn Euch das Bier schmeckt, das Ihr bekommen habt, und wir werden Euch noch mehr davon verkaufen. Dieser Verein gibt und gibt und gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12279] = { id = 12279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärenhunger", description = "Zum Glück seid Ihr zurück, Hinkejoe! Ich hatte Sorge, dass Griselda und ich ganz allein sein würden.\n\nIch koche uns gerade eine schöne Mahlzeit, aber Griselda will davon nichts wissen.\n\nSie hätte gerne den Fisch, der sich an der Ostwindküste im Osten tummelt. Für mich ist der ja nichts, aber sie war schon immer ziemlich wählerisch. Sechs große Fische sollten eigentlich reichen, um sie glücklich zu machen.\n\nNun, rennt... ähh... hinkt los, Joe. Wir wollen das Mädchen doch nicht warten lassen, oder?", sourceObjective = "Bringt Hugh Glass am Handelsposten von Rotholz 6 Nordlachse.", progress = "Wenn Ihr Euch nicht beeilt, wird hier gleich nicht nur ihr Magen knurren...", completion = "Ihr! Ihr seid ja gar nicht Hinkejoe!", sourceObjectiveStatus = "unverified-source-field" }
quests[12280] = { id = 12280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reparaturen", description = "Zwanzig Schredder bis morgen Mittag!\n\nWer macht diese Pläne überhaupt? Auf jeden Fall niemand, der diese Mülleimer schon mal wieder zusammensetzen musste, so viel ist mal sicher…\n\nWenn ich mein Soll erfüllen soll, dann brauche ich Unterstützung. Helft mir und ich teile meine Kommission mit Euch - das ist doch gerecht, oder?\n\nIch brauche Zahnräder, Winkel und Federn. Sie liegen überall auf dem Boden bei den Schreddern herum.", sourceObjective = "Lurz beim Holzfällerposten Blauhimmel möchte, dass Ihr 4 gefalzte Zahnräder, 3 gekerbte Winkel und 2 Hochspannungsfedern sammelt.", progress = "Und, habt Ihr die Teile für mich?", completion = "Danke, {name}. Das sollte die Arbeit am Laufen halten - bis morgen jedenfalls…\n\nHier ist das versprochene Geld.", sourceObjectiveStatus = "unverified-source-field" }
quests[12281] = { id = 12281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kriegsmaschine der Geißel verstehen", description = "Wir müssen uns mit dem Gedanken trösten, dass Schleichas Tod, wenn auch tragisch, dem Wohle aller gedient hat. Seine Entdeckung in Verbindung mit Euren Heldentaten in der Mine und den von Euch zurückgebrachten Proben bringen uns einen Schritt näher, die Kriegsmaschinerie der Geißel zu verstehen.\n\nBringt Viertelblitz' Paket zu Hochkommandant Halford Wyrmbann. In ihm befinden sich eine Probe des seltsamen Erzes und meine Analyse.", sourceObjective = "Liefert Viertelblitz' Paket bei Hochkommandant Halford Wyrmbann in der Feste Wintergarde ab.", progress = "Ich habe davon gehört, wie tapfer Ihr in der Mine gewesen seid, {name}.", completion = "<Halford öffnet das Paket und liest sich die Analyse durch.>\n\nIch bin weit davon entfernt, ein Wissenschaftler zu sein, {name}, Ihr müsst also mein pöbelhaftes Verständnis über das Geschriebene entschuldigen. Nun, sollte ich zumindest die Intelligenz eines heranwachsenden Schuljungens besitzen, dann lässt sich aus dieser Analyse schließen, dass wir noch rein gar nichts über die Kriegsmaschinerie der Geißel wissen. Das Einzige, was wir wissen, ist, dass die Geißel dieses schmutzige Metall zur Herstellung ihrer Belagerungsmaschinen verwendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12282] = { id = 12282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spuren der Vergangenheit", description = "Dieses Land wird von den Erinnerungen der Vergangenheit heimgesucht, {name}. Ich kann die Schreie der Gefallenen hören, wie sie über ganz Nordend hallen.\n\nArthas hat auf allem, das er berührt hat, ein schreckliches Mal hinterlassen. Es ist also wichtig für uns, etwas über die Vergangenheit zu lernen, damit wir unseren Feind besser verstehen können. Womöglich werden verborgene Wahrheiten zutage treten, die uns bei unserem Unternehmen helfen könnten.\n\nZuerst müsst Ihr meine Seherkugel aus dem Rathaus besorgen, {name}. Verlasst diesen Turm und biegt nach Links ab, den Pfad entlang, um zum Dorfplatz zu gelangen.", sourceObjective = "Zelig der Visionär in der Feste Wintergarde in der Drachenöde möchte, dass Ihr seine Seherkugel holt.", progress = "Habt Ihr meine Seherkugel geholt?", completion = "Gut gemacht, {name}. Wie vom Schicksal vorherbestimmt, werdet Ihr uns durch diese schweren Zeiten führen. Jetzt beginnt die lange Reise.", sourceObjectiveStatus = "unverified-source-field" }
quests[12283] = { id = 12283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wahrheit wird herauskommen", description = "Wir müssen herausfinden, was hier vorgeht - und dazu brauchen wir das Tagebuch des Generals!\n\nIch bin mir ziemlich sicher, dass es auf ihrem Nachtkästchen im oberen Stockwerk ihres Hauses liegt - das Haus neben der Kirche, gegenüber den Ställen und dem Sägewerk.\n\nBringt das Tagebuch zum Hochexekutor in Gallgrimm, sobald Ihr es gefunden habt.\n\nIhr werdet das wohl auf die altmodische Art und Weise machen müssen; der Spiegel besitzt nur noch wenig Energie - gerade noch genug für mich.\n\n<Die Agentin grinst.>", sourceObjective = "Agentin Skully möchte, dass Ihr das Tagebuch von Hochgeneralin Abbendis beschafft und es zu Hochexekutor Zürner in Gallgrimm bringt.", progress = "Es wurde auch langsam Zeit, {name}! Was hat Euch nur aufgehalten?", completion = "Verdammt! Wieso konntet Ihr mir keine guten Neuigkeiten bringen?!", sourceObjectiveStatus = "unverified-source-field" }
quests[12284] = { id = 12284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet sie auf Trab", description = "Wir mussten hier schlimme Verluste hinnehmen, {race}.\n\nDie einzige gute Nachricht ist, dass wir genauso viel ausgeteilt wie eingesteckt haben. Ich habe um Verstärkung gebeten, doch der Großteil unserer Truppen steckt in der Venturebucht fest. Sieht so aus, als ob wir fürs Erste auf uns allein gestellt wären.\n\nEgal, wie schlimm es wird, wir dürfen nicht zurückweichen! Die wertvollen Ressourcen, die diese Region bietet, sind ausschlaggebend für den langfristigen Erfolg der Horde in Nordend.\n\nWir müssen die Allianzler auf Trab halten, bis Hilfe eintrifft. Macht Euch auf den Weg und verpasst ihnen einen Denkzettel.", sourceObjective = "Kommandant Bargok möchte, dass Ihr beim Holzfällerposten Blauhimmel 15 Einheiten oder Spieler der Allianz tötet.", completion = "Fünfzehn umgelegt, hm? Schön, das zu hören, {class}.\n\nDas hat uns zumindest ein wenig Zeit erkauft - ich schätze wenigstens einen Tag.\n\nHier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12285] = { id = 12285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tu anderen...", description = "Ihr Angriff steht kurz bevor, {class}. Ihr müsst dort hineingehen und den Kopf des Scharlachroten Ansturms buchstäblich vom Rumpf abtrennen!\n\nEs wird nicht einfach sein... Abbendis wird sicherlich von einer großen Zahl ihrer Mannen umgeben sein.\n\nBringt mir ihren Kopf und ich werde dafür sorgen, dass Ihr für Gallgrimms Rettung eine anständige Belohnung erhaltet.\n\nSolltet Ihr jedoch versagen, dann kommt bloß nicht wieder zurück!", sourceObjective = "Hochexekutor Zürner in Gallgrimm hat Euch befohlen, mit dem Kopf der Hochgeneralin zurückzukehren.", progress = "Soll ich etwa meinen Truppen sagen, dass wir gen Agmars Hammer ziehen sollen?\n\nOder konntet Ihr den Hochgeneral töten?", completion = "Dann lasst uns mal sehen, ob sie ohne ihren Kopf wieder ins Leben gerufen werden kann!\n\n<Das Gelächter des Hochexekutors zieht etliche verstohlene Blicke auf sich.>\n\nIch mach' mir zwar ein wenig Sorgen darüber, dass Ihr diesen Großadmiral habt entkommen lassen, doch der Held des Tages seid Ihr allemal, {name}!\n\nSucht Euch etwas aus... Ihr habt es verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[12286] = { id = 12286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[12287] = { id = 12287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orik Treuherz und der Vergessene Strand", description = "Ich habe in die Kugel gesehen und sah den Pfad, den Ihr gehen müsst, {name}.\n\nVor vielen Jahren wurde ein Gräuel an den Küsten der Drachenöde begangen. Die Tat selbst verbleibt im Dunkel, doch ich bin sicher, dass Euer Schicksal im Süden liegt, inmitten der Ruinen des Vergessenen Strands.\n\nNehmt die Straße nach Südosten über den verwüsteten Dorfplatz. Folgt dem Pfad bis Ihr die Dämmerkuppe erreicht. Dort werdet Ihr einen meiner alten Freunde treffen, Orik Treuherz. Er wird Euch erwarten.", sourceObjective = "Sucht Orik Treuherz auf der Dämmerkuppe in der Drachenöde auf.", completion = "Zelig schickte Nachricht, mein Freund. Wir haben Euch erwartet.\n\nIch bin Orik Treuherz, Paladin des Argentumkreuzzugs. Die Priesterin auf der anderen Seite des Feuers ist Tilda Darathan. Wir sind im Namen der Argentumdämmerung hier, um die unglücklichen verdammten Seelen, die versuchen Wintergarde zu verlassen, zu bezwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12288] = { id = 12288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfordert!", description = "Ihr da, {class}! Helft mir!\n\nWertvolle Leben gehen verloren! Es gibt einfach viel zu viele Verwundete, als dass ich mich um sie alle alleine kümmern könnte. Wenn wir unsere Soldaten nicht heilen können, dann können wir gleich allesamt unsere sieben Sachen packen und aus den Grizzlyhügeln verschwinden!\n\nHier, nehmt diese Abschnürbinde und verbindet damit die unten auf dem Schlachtfeld liegenden Verwundeten.\n\nBeeilt Euch, {name}! Sie liegen im Sterben!!", sourceObjective = "Aumana beim Holzfällerposten Blauhimmel möchte, dass Ihr die erneuernde Abschnürbinde auf 10 verwundete Scharmützler anwendet.", completion = "Oh, ich danke Euch, ich danke Euch.\n\nDank Euch werden wir einen weiteren Tag erleben. Vielleicht gibt es noch Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12289] = { id = 12289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tritt rein, solang' sie am Boden liegen", description = "Dies ist ein schwarzer Tag für die Allianz. Viele gute Menschen sind tot oder liegen im Sterben. Unser einziger Trost ist, dass sie gut gekämpft und viele unserer Feinde mit in den Tod gerissen haben.\n\nDa der Großteil unserer Streitkräfte in der Venturebucht stationiert ist, müssen wir uns diesem Sturm alleine stellen. Die Ressourcen dieser Region sind für die Allianz essentiell und können das Zünglein an der Waage im Kampf gegen die Horde bedeuten. Wir dürfen nicht versagen!\n\nGeht nun, {name}. Schlagt zu, während sie noch ihre Wunden lecken. Nehmt Rache für Eure gefallenen Kameraden und seid das Licht unserer Hoffnung!", sourceObjective = "Unteroffizier Hartsmann möchte, dass Ihr 15 Einheiten oder Spieler der Horde im Holzfällerlager Blauhimmel besiegt.", completion = "Gut gemacht, {name}.\n\nIhr habt uns hier etwas Zeit verschafft, wenn auch wohl nicht mehr als einen Tag. Dennoch dankt Euch die Allianz für Euren Einsatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[12290] = { id = 12290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Düstergraselixier", description = "Die Geister der Verdammten spuken an der Küste umher. Zu Lebzeiten waren sie tapfere und ehrenhafte Soldaten der Allianz, doch im Tod sind sie verflucht. Wenn wir sie befreien wollen, müssen wir die Quelle ihrer Pein finden!\n\nIm Südosten, auf den Düsterhöhen werdet Ihr ein seltenes Kraut finden, das Düstergras genannt wird. Daraus werde ich ein Elixier zubereiten, welches Euch zeitlich begrenzten Zugang zur Welt der Vergessenen gewähren wird. Geht jetzt und sammelt das Gras.", sourceObjective = "Orik Treuherz auf der Dämmerkuppe in der Drachenöde möchte, dass Ihr 5 Düstergräser von den Düsterhöhen holt.", progress = "Habt ihr das Düstergras besorgt?", completion = "<Orik nimmt das Düstergras und beginnt, ein Elixier zu mixen.>\n\nEs dauert nicht mehr lange, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12291] = { id = 12291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vergessene Geschichte", description = "Die Toxine im Düstergraselixier werden Euch bewusstlos werden lassen. Die Wirkung des Düstergrases ist so stark, dass selbst Euer Geist getäuscht wird, wodurch Ihr für kurze Zeit in die Welt der Toten eintreten könnt.\n\nSobald Ihr dann ein Geist seid, müsst Ihr mit den geisterhaften Bewohnern des Vergessenen Strands reden. Findet die Quelle ihrer Pein und kehrt zu mir zurück.\n\nDenkt daran, {name}, diese Geister waren einst Soldaten der Allianz. behandelt sie mit Respekt, Ehre und Würde.\n\nNun nehmt das Elixier und wagt Euch nach Süden zum Vergessenen Strand.", sourceObjective = "Hört Euch die Geschichte der vergessenen Arbeiter, vergessenen Scharfschützen, vergessenen Ritter und der vergessenen Fußsoldaten an.", progress = "Ich habe genug Düstergras, um noch mehr Elixiere herzustellen, {name}.", completion = "<Tränen sammeln sich in Oriks Augen.>\n\nSie wissen es nicht. Keiner von ihnen weiß es! Sie halten Arthas für einen großen Helden, wo es in Wirklichkeit doch Arthas war, der die Schiffe verbrennen lies. Es war Arthas der uns in dieser gefrorenen Öde dem Tod überließ!\n\n<Orik weint.>\n\nNicht alle Soldaten der Flotte des Prinzen sind im frostigen Winter umgekommen. Ich war nur ein Jüngling, als ich die Chance bekam, gegen die Geißel zu kämpfen... und unsere Heimat vor der sicheren Zerstörung zu retten. Ich ergriff diese Chance, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12292] = { id = 12292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unterstützung der Einheimischen", description = "Der Kampf mit der Horde ist in den Grizzlyhügeln zum Stillstand gekommen. Unsere Streitkräfte sind fast gleich stark und alle Zeichen deuten darauf hin, dass wir eine Pattsituation erreicht haben.\n\nBis zu diesem Morgen jedenfalls. Die einheimischen Fallensteller und Pelzjäger haben um unsere Hilfe gebeten. Anscheinend hat die Horde etwas, das ihnen gehört... Irgendein Relikt.\n\nWir holen es ihnen zurück und gewinnen dank ihrer Unterstützung den Vorsprung, den wir benötigen. Macht Euch auf zum Handelsposten Immergrün, westlich von Burg Siegeswall, und seht Euch nach einer Zedernholzkiste um.", sourceObjective = "Leutnant Dumont bei der Ammertannhütte möchte, dass Ihr Euch zum Handelsposten Immergrün begebt und die Zedernholzkiste beschafft.", progress = "Habt Ihr die Kiste für mich, {name}?", completion = "Sie ist verschlossen, oder? Sieht ziemlich gewöhnlich aus.\n\n<Leutnant Dumont schüttelt die Kiste, was ein hölzernes Klappern hervorruft.>\n\nIch denke, das macht nichts. Solange uns das hier einen Vorsprung gegenüber der Horde verschafft, ist es mir auch egal, wenn hier drin das Heilmittel gegen die Seuche wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[12293] = { id = 12293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schließt den Handel ab", description = "Wir haben, was die Fallensteller wollen. Nun ist es an uns, sie auf unsere Seite zu bringen.\n\nBringt die Kiste zu einem Fallensteller namens Ivan im Posten des Espenhains, gleich nördlich von hier.\n\nWenn alles gut geht, werden wir bald Waldmänner als Späher für die königliche Armee einsetzen können.", sourceObjective = "Bringt die Zedernholzkiste zu Ivan im Posten des Espenhains.", progress = "Habt Ihr etwas für uns?", completion = "Ihr habt es geschafft! Ihr habt die Kiste, welche die Horde uns gestohlen hat, zurückgebracht. Wir danken Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12294] = { id = 12294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vorläufiger Pakt", description = "Nun gut, {name}. Euer Volk hat seinen Teil der Abmachung eingehalten.\n\nSagt Dumont, dass wir auch unseren Teil einhalten werden.", sourceObjective = "Kehrt zu Leutnant Dumont in der Ammertannhütte zurück.", completion = "Ausgezeichnete Arbeit, {name}. Mit der Hilfe der Einheimischen steht uns auch die logistische Unterstützung zur Verfügung, die wir dazu brauchen, um die Horde in dieser Region auszumanövrieren.\n\nIch habe noch mehr Aufgaben für Euch, falls Ihr daran interessiert seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[12295] = { id = 12295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Übung in Sachen Diplomatie", description = "Wir hatten wochenlang versucht, mit den Fallenstellern zu verhandeln, jedoch erfolglos, bis Ihr ihre verdammte Kiste gefunden habt.\n\nDas sollten gute Neuigkeiten für unseren Entsandten in Silberwasser sein. Vor ungefähr einer Woche haben wir Ducal dorthin geschickt und sein letzter Brief lässt darauf schließen, dass er nur wenig Fortschritt gemacht hat.\n\nGeht nach Silberwasser und helft ihm bei seinen diplomatischen Angelegenheiten. Folgt den Straßen in Richtung Nordwesten. Nach ein paar Brücken solltet Ihr dort ankommen.", sourceObjective = "Sprecht mit dem Entsandten Ducal in Silberwasser.", completion = "Gut, Euch endlich kennenzulernen, {name}! Wir haben hier oben von Euch gehört. Willkommen in Silberwasser.\n\nDiese Fallensteller sind ein toller Haufen Jungs und Mädels. Ein hartes Völkchen - sie kennen sich sehr gut mit dem hiesigen Gelände aus. Ihr werdet sehen, dass es eine großartige Sache ist, dass wir sie endlich auf unsere Seite geholt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12296] = { id = 12296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leben oder Tod", description = "Oh, dieses Gemetzel...\n\nIch habe schon viele Schlachten erlebt, {class}, aber das war brutaler als alles, was ich bisher gesehen habe. Unser Kampf gegen die Horde ist erbarmungsloser denn je geworden. Es heißt hier in Nordend sie oder wir... Leben oder Tod.\n\nWenn wir hier auch nur einen Tag länger überleben wollen, müssen wir unsere Verletzten heilen. Es sind zu viele, als dass ich sie alleine retten könnte.\n\nIch habe besondere Verbände hergestellt, die es ermöglichen, dass Ihr mir helfen könnt. Nehmt sie und behandelt diejenigen damit, die ihren Wunden noch nicht erlegen sind.", sourceObjective = "Rheanna beim Holzfällerposten Blauhimmel möchte, dass Ihr die erneuernde Bandage bei 10 verwundeten Westfall-Einheiten anwendet.", completion = "Wundervoll!\n\nDie Allianz wird noch einen weiteren Tag erleben, nicht zuletzt dank Eures Fleißes.\n\nNehmt meinen Dank an, Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[12297] = { id = 12297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Verrätern und Verrat", description = "Die Liste, die ich in Händen halte, muss an Hochkommandant Halford Wyrmbann überbracht werden. Er kommandiert die 7. Legion, die in der Feste Wintergarde an der östlichen Grenze der Drachenöde stationiert ist.\n\nWenn sich irgendeiner der Verräter auf dieser Liste in Wintergarde befindet... könnten die Folgen katastrophal sein.\n\nBeeilt Euch, {name}. Zeigt Greer Erzhammer hier in Westwacht dieses Schreiben und erklärt ihm, was es mit Eurer Mission auf sich hat. Für die Reise nach Wintergarde wird er Euch seinen schnellsten Greifen geben!", sourceObjective = "Hauptmann Adams möchte, dass Ihr das Schreiben der Allianz zu Greer Erzhammer in Westwacht bringt.", progress = "Hallo, {class}.", completion = "<Greer schiebt seine Brille auf die Stirn, liest sich die Mitteilung durch und blickt Euch verwundert an.>\n\nIch werde Euch meinen schnellsten Greifen geben! Diese Information muss unverzüglich an Oberkommandant Wyrmbann ausgehändigt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12298] = { id = 12298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochkommandant Halford Wyrmbann", description = "<Greer gibt Euch das Schreiben wieder zurück.>\n\nHimmelsweise wird Euch nach Wintergarde bringen, {name}. Ich kann Euch versichern, dass dies der schnellste Flug sein wird, den Ihr je erlebt habt. Geht jetzt!", sourceObjective = "Überbringt Hochkommandant Halford Wyrmbann das Schreiben der Allianz. Er befindet sich in der Feste Wintergarde im Osten der Drachenöde.", progress = "Was habt Ihr denn da, Soldat?", completion = "<Der Oberkommandant liest sich das Schreiben durch und zerknüllt es anschließend.>\n\nWisst Ihr, wo sich diese Leute auf der Liste im Moment befinden? Seht Euch draußen in der Nähe des Eingangstores einmal um. Es sind diejenigen, die vom Torbogen baumeln.\n\nGhulköder...", sourceObjectiveStatus = "unverified-source-field" }
quests[12299] = { id = 12299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nördliche Gastfreundschaft", description = "Gut, Euch zu sehen. Lasst uns unseren Pakt zelebrieren, indem wir zünftig auf Hordejagd gehen.\n\nIhr findet außerhalb der Stadt im Westen einige Marodeure von Burg Siegeswall. Warum begebt Ihr Euch nicht dorthin und bringt sie wie räudige Tiere, die sie ja auch sind, zur Strecke?\n\nLasst uns doch mal sehen, ob unsere neuen Verbündeten ihren großen Worten auch Taten folgen lassen.", sourceObjective = "Sergei in Silberwasser will, dass Ihr 8 Marodeure von Burg Siegeswall tötet.", progress = "Habt Ihr diese Amateure schon fertiggemacht?", completion = "Nicht schlecht, nicht schlecht. Am Ende seid Ihr nicht ganz so weich wie manche der anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12300] = { id = 12300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eignungstest", description = "Gut, <Freund/Freundin>. Ihr habt uns einen oder zwei Gefallen erwiesen, aber das alleine zeugt nicht von Mut.\n\nIn dieser Gegend seid Ihr kein wahrer Jäger, solange Ihr nicht die Haut Eurer Beute tragt.\n\n<Sergei zieht sein Kürschnermesser aus der Scheide und reicht es Euch.>\n\nDer Anführer dieser mutterlosen Orcs, die unsere Stadt angreifen, wird Knochenknacker genannt; Ihr findet ihn in einem Lager weiter nordwestlich von hier.\n\nJa, richtig. Ihr werdet das Monster häuten.", sourceObjective = "Findet Unteroffizier Knochenknacker nordwestlich von Silberwasser und besteht den Eignungstest.", completion = "Tut es nicht, {name}. Die Leute, die Euch hierher sandten... Ihr dürft ihnen nicht trauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12301] = { id = 12301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Möge die Wahrheit uns befreien", description = "Zelig hat mir vor Jahren diese Kristallkugel mit speziellen Anweisungen zu ihrer Verwendung übergeben. Fünf Jahre lang - wann auch immer ich Wut, Angst oder Kummer bezüglich des hier Geschehenen verspürte - sollte ich meine Gedanken auf diese Kugel konzentrieren.\n\nJetzt verstehe ich, wieso Zelig mir diese Kugel gab.\n\nBringt meine kristalline Kugel zum Vergessenen Strand. Findet die Ruinen meiner alten Basis in den oberen Gefilden des Strands und legt die Kugel in die Mitte der Stadt. Lasst die Vergessenen die Welt mit meinem Herzen und meiner Seele sehen.", sourceObjective = "Setzt Oriks kristalline Kugel in den Ruinen des Vergessenen Strands ein, um die Vergessenen zu erlösen.", progress = "Ist es vollbracht?", completion = "<Orik wirft Euch ein Lächeln entgegen.>\n\nIhr habt heute eine gute Tat vollbracht, {name}. Hunderte verlorener Seelen wurden nun Dank Euch erlöst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12302] = { id = 12302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte der Warnung", description = "Danke, dass Ihr mir helft, {name}. Mein Name ist Sasha. Hört zu, ich muss so schnell wie möglich von hier verschwinden.\n\nDie Leute, die Euch hergeschickt haben… meine Leute… sie haben sich verändert. Sie sind keine guten Leute mehr… und wollen, dass Ihr Euch in... in einen von ihnen verwandelt.\n\nDieser... \"Test\", mit dem sie Euch beauftragt haben, ist nur der Anfang.\n\nBegebt Euch zum nordwestlichen Ende von Silberwasser. Dort werdet Ihr etwas Interessantes finden...\n\nViel Glück... und vertraut niemandem.", sourceObjective = "Begebt Euch zum nordwestlichen Ende von Silberwasser.", completion = "Wer ist da? Seid Ihr hier, um mich zu töten?\n\nBitte! Das müsst Ihr nicht tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[12303] = { id = 12303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kriegsanstrengungen finanzieren", description = "<Der Rüstmeister senkt seine Stimme und flüstert Euch zu.>\n\n{class}, ich brauche Eure Hilfe - unsere Truhen sind leer. Unsere gesamten Mittel sind an den Vorposten der Kor'kron und den Kampf an der Pforte des Zorns gegangen.\n\nMir wurde jedoch zugeflüstert, dass sich auf den Schiffswracks am Vergessenen Strand im Südosten Schätze ergattern lassen.\n\nWir müssen schon bald etwas unternehmen oder wir werden den Kampf gegen den Scharlachroten Ansturm nicht weiterführen können. Krieg ist nicht gerade billig, müsst Ihr wissen!", sourceObjective = "Quartiermeister Bartlett in Gallgrimm möchte, dass Ihr 6 vergessene Schätze beschafft.", progress = "Wie viel von den Allianzschätzen konntet Ihr in Eure Finger bekommen?", completion = "<Dem Rüstmeister stockt der Atem, worauf er Euch einen Moment lang skeptisch mustert.>\n\nIch vertraue einmal darauf, dass Ihr nichts von dem Gold für Euch selbst behalten habt? Ich denke nicht, dass Ihr angesichts dessen, dass hier das Schicksal von Gallgrimm auf dem Spiel steht, so selbstsüchtig sein könntet, oder?\n\nAußerdem werde ich Euch prozentual am Gewinn beteiligen. Es ist zwar nicht viel, doch in Zeiten wie diesen, muss ein jeder Opfer bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12304] = { id = 12304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Grundstück am Strand", description = "Es ist Zeit, dass Gallgrimm expandiert!\n\nWir werden uns um den Scharlachroten Ansturm schon rechtzeitig kümmern, doch zuerst möchte ich, dass Ihr dafür sorgt, dass unsere Anstrengungen am Vergessenen Strand zum Ziel führen. Die Grundstücke dort versprechen einiges, und habt Ihr schon die Aussicht gesehen?\n\nUnglücklicherweise ist der Ort nur so von Menschengeistern, gestrandeten Mannschaften und dergleichen verpestet. Sie wollen einfach nicht wahrhaben, dass sie tot sind.\n\nSäubert den Strand und die Gewässer vor der Küste und wir beide könnten vielleicht darüber reden, dort unten schon bald ein gemütliches, neues Mausoleum zu bauen.", sourceObjective = "Feldmesser Hansen gleich nördlich des Vergessenen Strands möchte, dass Ihr 20 vergessene Geister vernichtet.", completion = "Habt Ihr's jetzt vor Augen, {class}? Es wird DER Urlaubsort in Nordend schlechthin!\n\nWie gefällt Euch denn der Name \"Hansens Bucht\" oder vielleicht \"Bucht von {name}\"? Hat was, findet Ihr nicht auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[12305] = { id = 12305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedanken des Abschieds", description = "Ihr habt mir und Hunderten von Veteranen der Allianz Ehre erwiesen, {name}. Es war weise von Zelig, Euch hierher zu schicken. Bitte geht zu ihm zurück und überbringt ihm meinen Dank. Er wird über das, was am Vergessenen Strand geschehen ist, erfreut sein.\n\nDie Gabe, in die Zukunft zu blicken, wurde mir zwar, im Gegensatz zu Zelig, nicht zu Teil. Dennoch bin ich sicher, dass Großes auf Euch wartet, <mein Freund/meine Liebe>.\n\nLebt wohl.", sourceObjective = "Kehrt zu Zelig dem Visionär in der Feste Wintergarde in der Drachenöde zurück.", completion = "<Zelig lächelt.>\n\nIch fühle mich Euch zu tiefster Dankbarkeit verpflichtet, mein Held. Orik ist für mich wie ein Bruder. Ihr habt sein Leben verändert und den Hoffnungen zahlloser anderer neues Leben eingehaucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12306] = { id = 12306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bier des Monats e.V.", description = "Gemeinsam ist man stark, {name}. Ein Mitglied des \"Bier des Monats e.V.\" hat immer das beste Bier zur Hand.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in Orgrimmar.", sourceObjective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in Orgrimmar.", progress = "Habt Ihr Euren Antrag ausgefüllt?", completion = "Du wirst dich uns anschließen, {name}? Wir sind gut zu dir, Mann. Wenn du bei diesem Verein mitmachst, bekommst du nur das Beste!\n\nZu Monatsbeginn schicken wir dir Bier. Wenn's dir schmeckt, dann komm doch wieder hierher. Wir sorgen dafür, dass du noch mehr davon bekommst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12307] = { id = 12307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsbannwurzel", description = "Habt Ihr schon von der Wolfsbannpflanze gehört? Es ist ein schreckliches Unkraut... es zerstört unsere Ernte.\n\nWir haben die ganze letzte Woche damit verbracht, es zu beseitigen, doch die Wurzeln fangen wieder an zu sprießen.\n\nEs mag vielleicht nicht dringend erscheinen, doch ein Wiederaufleben der Pflanze könnte eine wahre... Katastrophe sein. Denkt Ihr, dass Ihr uns dabei helfen könntet, die Wurzeln in der Nähe des Dorfes herauszureißen?", sourceObjective = "Katja in Silberwasser möchte, dass Ihr 8 Wolfsbannwurzeln ausreißt.", completion = "<Katja schwankt und wendet sich nervös von Euch ab.>\n\nIch danke Euch, {name}. Ihr seid nicht mit Wolfsbann in Berührung gekommen, oder? Ich hab' diese... Allergien, die mir hin und wieder Probleme bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12308] = { id = 12308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Silberwasser", description = "Ihr... Ihr seid keiner von ihnen? Schnell! Lasst mich raus!\n\nWir müssen schleunigst zur Ammertannhütte! Wenn Leutnant Dumont erst einmal herausfindet, wer diese Leute wirklich sind, dann wird diese Stadt in Schutt und Asche gelegt werden!", sourceObjective = "Öffnet den hölzernen Käfig und helft dem befreiten Späher der Allianz, aus Silberwasser zu entkommen. Meldet Euch bei Leutnant Dumont, sobald Ihr die Ammertannhütte erreicht habt.", completion = "Worgen. Verdammte, vom Licht verlassene, dreckige Worgen.\n\nEs ist an der Zeit, dass wir den Einheimischen zeigen, was zivilisierte Leute mit Bestien, wie sie es sind, machen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12309] = { id = 12309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Durkon!", description = "Nachdem die Geißel an der Südmauer durchgebrochen war, habe ich Dragoner Durkon befohlen, die örtliche Gruft zu untersuchen. Vor wenigen Augenblicken habe ich seinen Bericht erhalten.\n\nDie Untoten, die uns heimsuchen, kommen aus zwei Quellen: den Ruinen von Wintergarde, die nun eine Brutstätte der Geißel sind, und aus unserer eigenen Gruft! In all dem Chaos und der Verwirrung hat es die Geißel geschafft, einen Nekrolord in die Gruft zu bekommen.\n\nIn seiner Nachricht bat Durkon um Unterstützung. Ihr werdet ihn suchen und ihm helfen, {name}. Die Gruft befindet sich an der westlichen Grenze des Dorfplatzes.", sourceObjective = "Sucht Dragoner Durkon bei der Gruft von Wintergarde in der Drachenöde auf.", completion = "Oh Junge, hier unten ist die Hölle los! Ich habe es beim letzten Mal kaum lebend herausgeschafft - weshalb ich dann die Bitte an den Hochkommandaten gestellt habe.\n\n<Durkon mustert Euch von oben bis unten.>\n\nIhr habt diesen irren Blick in Euren Augen, {race}. Glücklicherweise muss man irre sein, um das zu tun, was ich gleich von Euch verlangen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[12310] = { id = 12310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine prompte Reaktion", description = "Unsere Reaktion muss prompt erfolgen. Und entschlossen. Wir müssen diesen Wilden zeigen, dass sie sich besser nicht mit uns anlegen sollten.\n\nUnsere Späher haben die restlichen Fährtenleser von Silberwasser ausfindig gemacht… Ihr wisst schon, die, die nicht in den Flammen umgekommen sind. Anscheinend blockieren sie die Straße nach Südosten... vielleicht versuchen sie ja, uns einzukreisen.\n\nBegebt Euch zum Posten des Waldrandes und kümmert Euch um sie. Ihr Anführer ist angeblich ein Mann namens Vladek... stellt sicher, dass er auf der Strecke bleibt.", sourceObjective = "Leutnant Dumont möchte, dass Ihr zum Posten des Waldrands geht und Vladek sowie 7 Fährtenleser von Silberwasser erledigt.", completion = "Was für eine Schande, dass sich diese Fährtenleser als… befallen herausgestellt haben. Wir hätten schon noch ein paar mehr Kämpfer gebrauchen können.\n\nMögen ihre armen Seelen in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12311] = { id = 12311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gruft des Adligen", description = "Innerhalb der kalten Steinmauern dieser Gruft liegen die Gebeine der Adligen und der Würdenträger Nordends. Im Herzen dessen sitzt jetzt ein Nekrolord und erweckt die Leichen als Diener der Geißel wieder.\n\nIhr müsst es bis zum Ende der Gruft schaffen und Nekrolord Amarion töten. Nur dann wird der Angriff aus dem Inneren der Gruft zum erliegen kommen!\n\nUnd, {name}, haltet Ausschau nach allen Informationen, die sich in dem Raum verbergen, in dem Amarion haust.", sourceObjective = "Dragoner Durkon in der Feste Wintergarde möchte, dass Ihr Nekrolord Amarion tötet.", completion = "Wenn wir es jetzt schaffen, die Angriffe der Geißel vom Äußeren der Feste zu stoppen, schaffen wir es vielleicht, Hilfe zu Lord Fordragon an der Pforte des Zorns zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[12312] = { id = 12312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Geißel", description = "Um die fleischgebundenen Kapitel dieses Folianten herum sind seltsame Symbole gekritzelt sowie Formen, die mit einer Klinge in die Seiten gekratzt worden zu sein scheinen. Ihr habt keine Ahnung, was dort geschrieben steht, doch Ihr seid Euch sicher, dass, was auch immer es sein mag, es wichtig ist.\n\nÜbergebt den Folianten an Dragoner Durkon, welcher an der Oberseite der Gruft von Wintergarde Wache hält.", sourceObjective = "Bringt den fleischgebundenen Folianten zu Dragoner Durkon in der Feste Wintergarde in der Drachenöde.", progress = "Ein Foliant der Geißel?", completion = "Welche Informationen dieses Buch auch birgt, sie müssen von großer Bedeutung sein! Als Ihr auf der Flucht wart, konnte ich das Heulen und Klagen durch die Gruft hallen hören!\n\nDer Oberkommandant muss darüber in Kenntnis gesetzt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12313] = { id = 12313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet das Braufest!", description = "Rettet das Braufest! Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen.", sourceObjective = "Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12314] = { id = 12314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit Kapitänin Zorna!", description = "Die Streitkräfte der Horde sind kurz davor, unsere Reihen zu durchbrechen und die Eroberung der Venturebucht abzuschließen, wenn wir nicht handeln. Ihre Soldaten werden dabei von Kapitänin Zorna angeführt, in der Nähe des Schiffs an der abgelegenen Seite der Bucht.\n\nWenn Ihr sie besiegen könnt, bricht die Offensive der Horde zusammen und wir können den Hafen einnehmen. Seid auf der Hut, {name}, denn Zorna ist eine starke Kämpferin. Ihr werdet mehrere Leute brauchen, um sie zu besiegen, es sei denn, Ihr habt Zugang zu einem reparierten Schredder. Den könntet Ihr zu Eurem Vorteil einsetzen.", sourceObjective = "Tötet Kapitänin Zorna und erstattet Baron Freimann in der Venturebucht Bericht.", completion = "Gut gemacht, {name}! Ohne ihre Anführerin ist die Horde schwach und unorganisiert. Ich werde unsere Männer zum Angriff formieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12315] = { id = 12315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschmettert Kapitän Hellwasser!", description = "Mit jedem Vorrücken treffen unsere Männer auf frische Truppen der Allianz, so als ob ihr Kommandant jeden meiner Schritte vorausahnen würde!\n\nEs ist an der Zeit, dass für den guten Kapitän Hellwasser die letzte Stunde schlägt. Er befehligt seine Truppen von Bord eines Zerstörers der Allianz am anderen Ende der Bucht.\n\nDas wird kein einfacher Kampf, {name}! Zieht mit ein paar vertrauensvollen Freunden los oder schlitzt Hellwasser mit einem der reparierten Schredder auf, falls Ihr einen Schlüssel dafür besitzt! So oder so - er muss sterben!", sourceObjective = "Tötet Kapitän Hellwasser und erstattet anschließend General Khazgar in der Venturebucht Bericht.", completion = "Ihr seid ein wahrer Soldat der Horde, {name}! Euer Mut wird meine Männer zum Sieg führen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12316] = { id = 12316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet sie auf!", description = "Wir können nicht zulassen, dass die Horde die Venturebucht kontrolliert. Der Hafen ist für unsere Operationen in den Grizzlyhügeln und dahinter überlebenswichtig.\n\nHauptmann Starkmantel ist mit dem Rest der Westfallbrigade nach Osten aufgebrochen, um einen Weg durch die Berge zu finden, also haben wir keine Verstärkung mehr.\n\nWerft Euch in die Schlacht, {name}, und tötet die Berserker aus Burg Siegeswall, welche die Horde gegen uns gesandt hat. Mäht sie nieder, bis keiner mehr steht. Die Allianz muss diesen Hafen einnehmen!", sourceObjective = "Besiegt 10 Einheiten oder Spieler der Horde in der Venturebucht und kehrt zu Leutnant Stuart zurück.", completion = "Eure Tapferkeit hat die Männer der Westfallbrigade inspiriert. Nun kämpfen sie mit noch größerer Entschlossenheit. Der Hafen wird bald unser sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12317] = { id = 12317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet sie auf!", description = "Diese vermaledeite Westfallbrigade stellt sich als härterer Gegner heraus, als wir gedacht haben. Obwohl sie nur wenige sind, kämpfen sie gut und tapfer, und wir können es uns nicht leisten, abzuwarten.\n\nDer Befehl Eroberin Krennas lautet, den Hafen schnell einzunehmen. Ihr müsst die Pattsituation aufheben, {name}. Findet die Marinesoldaten des Gegners und schlachtet sie ab, bis der Widerstand gebrochen ist. Erst dann können wir den Hafen einnehmen.\n\nBeeilt Euch. Wir wollen Eroberin Krenna nicht warten lassen.", sourceObjective = "Besiegt 10 Einheiten oder Spieler der Allianz in der Venturebucht und kehrt zu Zenturion Kaggrum zurück.", completion = "Der Hafen wird bald unser sein. Ihr habt uns heute einen großen Dienst erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12318] = { id = 12318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet das Braufest!", description = "{name}, unsere Spione haben ein teuflisches Komplott ans Licht gebracht! Die Dunkeleisenzwerge wollen unser geliebtes Braufest dem Erdboden gleichmachen!\n\nCoren Düsterbräu, Oberhaupt einer abtrünnigen Familie von Braumeistern, hat die Zwerge der Schwarzfelstiefen mobilisiert, zudem werden wir auch noch ständig von ihren Maulwurfmaschinen angegriffen.\n\nUnser Spion befindet sich im Grimmigen Säufer, einer Taverne im Inneren der Schwarzfelstiefen. Er wird mehr über Düsterbräus Komplott wissen.\n\nSucht unseren Spion aus. Rettet das Braufest!", sourceObjective = "Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12319] = { id = 12319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rätsel des Folianten", description = "Worum könnte es sich handeln, {name}? Es handelte sich bestimmt um keinen gewöhnlichen Fluch, den der verdammte Lich auf Euch gelegt hat!\n\n<Durkon blättert die entsetzlichen Seiten des Folianten durch.>\n\nIch weiß nicht einmal, ob ich es richtig herum halte. Wir müssen herausfinden, welche Informationen dieser Foliant birgt!\n\n<Durkon gibt Euch das Buch.>\n\nDer Oberkommandant wird wissen, was zu tun ist. Bringt ihm den fleischgebundenen Folianten und schildert ihm genau, was hier vorgefallen ist.", sourceObjective = "Übergebt Hochkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde den fleischgebundenen Foliant.", progress = "Der Nekrolord ist Geschichte?", completion = "<Halfords Augen öffnen sich weit.>\n\nDas Schicksal lächelt heute auf uns herab, {name}. Ich kenne genau den Richtigen, den man wegen dieses Folianten aufsuchen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[12320] = { id = 12320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sprache des Todes verstehen", description = "Nehmt das Buch und folgt dem Pfad zur Kaserne. Nehmt in der Kaserne die Treppe hinunter zum Gefängnis. Dort werdet Ihr Inquisitor Hallard und unseren Bürgermeister Gottfried finden. Ich glaube, dass Gottfried das fehlende Teil dieses Puzzles ist und das Hallard genau der richtige ist, um daraus ein vollständiges Bild zu machen.\n\nGeht!", sourceObjective = "Bringt den fleischgebundenen Folianten zu Inquisitor Hallard im Gefängnis der Feste Wintergarde.", progress = "Kommt Ihr vom Oberkommando, mein Sohn?", completion = "Mit der entsprechenden Motivation wird uns Gottfried vielleicht verraten, was er darüber weiß.\n\n<Hallard wendet sich Bürgermeister Gottfried zu.>\n\nNicht wahr, Bürgermeister?", sourceObjectiveStatus = "unverified-source-field" }
quests[12321] = { id = 12321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine rechtschaffene Predigt", description = "Gottfried Guters, einst ein rechtschaffener Mann und Bürgermeister von Wintergarde, arbeitet nun für die Geißel. Seine Verwandlung vom Menschen zu einem untoten Ghul kam langsam und mit der Zeit. Nun hört er den Ruf des Lichkönigs und lebt nur noch, um seinem Meister zu dienen.\n\nDoch wie alle Mitglieder der Geißel beherrscht Gottfried die Sprache des Todes und mit der richtigen Überredungskunst wird er uns erzählen, was wir über den Folianten wissen müssen.\n\nKehrt zum Oberkommandanten an die Front zurück, sobald Ihr gehört habt, was Ihr hören sollt. Ich werde hier dementsprechend aufräumen.", sourceObjective = "Wartet, bis Inquisitor Hallard seine rechtschaffene Predigt gehalten hat, und kehrt dann mit Euren Entdeckungen zu Hochkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde zurück.", completion = "Wir hätten über das verfluchte Mausoleum Bescheid wissen sollen. Das ist absurd! Herzog August Feindhammer und Ambo Unkesch werden zur Vorbereitung des nächsten Angriffs an die Front geschickt werden.\n\nSobald Ihr die Minen geräumt habt, werde ich Euch zu Feindhammer schicken, sodass wir mit unserem Angriff auf die Geißel von Naxxramas beginnen können!\n\nDie bisher von Euch gesammelten Informationen werden von unseren fähigsten Greifen zu Lord Fordragon an die Pforte des Zorns gebracht werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12323] = { id = 12323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuchert sie aus", description = "In einigen der Gebäuden hier in der Mitte der Venturebucht gibt es noch immer vereinzelte Gruppen von feigen Mitarbeitern der Venture Company. Ich brauche zwar jeden Mann, den ich entbehren kann, da draußen für den Kampf gegen die Horde, jedoch können wir genauso wenig zulassen, dass diese Nachzügler der Venture Company in diesen Gebäuden campieren.\n\nVielleicht können wir sie davon \"überzeugen\", auf ihr Schiff zurückzukehren. Nehmt diese Rauchbombe hier und räuchert mit ihr die Nachzügler in der Baracke, dem Sägewerk oder im Stall aus. Geht jedoch nicht zu nah ran - wahrscheinlich beißen sie.", sourceObjective = "Jagt mithilfe der Rauchbombe 20 Nachzügler der Venture Co. aus ihren Gebäuden und meldet Euch anschließend bei Unteroffizier Downey.", completion = "Gut gemacht, Soldat! Nun kann sich der Rest der Männer auf die Horde konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12324] = { id = 12324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuchert sie aus", description = "Es ist ja nicht nur so, dass dieser Hafen lediglich mit feigen Allianzheulsusen verpestet wäre, nein, denn um die Sache noch schlimmer zu machen, gibt es noch immer Mitarbeiter der Venture Company, die sich in einigen Gebäuden verkrochen haben. Es ist einfach reine Zeitverschwendung, sie zu töten, und ich kann sowieso keine Krieger entbehren.\n\nVielleicht können wir sie davon \"überzeugen\", auf ihr Schiff zurückzukehren. Nehmt diese Rauchbombe hier und räuchert mit ihr die Nachzügler in der Baracke, dem Sägewerk oder im Stall aus. Geht jedoch nicht zu nah an sie ran - man kann nie wissen, welche Krankheiten sie in sich tragen.", sourceObjective = "Jagt mithilfe der Rauchbombe 20 Nachzügler der Venture Co. aus ihren Gebäuden und meldet Euch anschließend bei Steingardist Rachtotem.", completion = "Der General wird sehr darüber erfreut sein, dass Ihr Euch um die Venture Company gekümmert habt. Nun können sich die Männer darauf konzentrieren, die Allianz zurückzuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12325] = { id = 12325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein ins Feindgebiet", description = "Ihr habt viel zu unserem Kampf gegen die Geißel beigetragen, {name}. Tatsächlich steigt die Moral derjenigen, die mit Euch in Berührung gekommen sind, rasant an! Solch einen Einfluss habt Ihr auf die Soldaten und Bewohner von Wintergarde, <Verbündeter/Verbündete>.\n\nUnd es ist Euch zu verdanken, dass wir nun darauf vorbereitet sind, in die Offensive zu gehen! Ihr sollt Euch bei Herzog August Feindhammer melden. Er befindet sich auf der anderen Seite der Aasfelder bei Thorsons Posten, östlich von hier. Greifenkommandant Urik an der Greifenstation hat einen speziellen Greifen bereitgestellt, der Euch hinter Feindeslinien absetzen wird. Geht jetzt!", sourceObjective = "Sprecht mit Greifenmeister Urik und fliegt zu Thorsons Posten. Meldet Euch bei Herzog August Feindhammer, wenn Ihr bei Thorsons Posten in der Drachenöde angekommen seid.", completion = "Ah, der namhafte Held ist angekommen. Willkommen im Zentrum des Geschehens, {name}. Erlaubt mir, Euch auf den neuesten Stand zu bringen!\n\nThel'zans stärkste Truppen haben sich bis ins Mausoleum von Wintergarde durchgekämpft. Sie erkunden seine Tiefen auf der Suche nach Leichen und Seelen, um sie auf Wintergarde zu hetzen, während Naxxramas schreckliche Seuchenmaschinen der Geißel auf uns niederprasseln lässt, um uns in Schach zu halten!\n\nWir müssen jetzt zuschlagen und darauf hoffen, dass Lord Fordragon bei den Zornpforten noch etwas länger durchhalten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12326] = { id = 12326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dampfpanzerüberraschung", description = "Diese Mission dreht sich nur um eins: Suchen und Vernichten. Ihr werdet mit einem Panzer in die Aasfelder fahren und die Seuchewagen in ihre Einzelteile zerlegen. Der Panzer wird von drei Soldaten der 7. Legion begleitet, die alle überleben müssen, wenn die Mission erfolgreich enden soll!\n\nIhr werdet nah an einen Seuchewagen heranfahren müssen, um Euren Ingenieur einzusetzen. Sobald es keine Seuchewagen auf dem Feld mehr gibt, bewegt Euch in Richtung des Mausoleums, das sich vor der zerstörten Festung befindet, und setzt den Rest Eures Trupps ab. Trefft Euch im Inneren des Mausoleums mit Ambo Unkesch.", sourceObjective = "Zerstört mithilfe des Dampfpanzers der Allianz 6 Seuchewagen und ladet die Elitesoldaten der 7. Legion beim Mausoleum von Wintergarde ab. Sprecht anschließend mit Ambo Unkesch im Inneren des Mausoleums von Wintergarde, wenn Eure Aufgabe erledigt ist.", completion = "Wieso ich keine Hosen trage, ist nicht wichtig. Sagen wir einfach mal, dass mich ein Schrapnell der Geißel am falschen Ort getroffen hat und belassen es dabei, in Ordnung?\n\nDu hast also die Seuchewagen auf den Feldern alle gemacht und meine Soldaten in einem Stück hier abgeliefert. Beeindruckend. Du bist einer der Ersten, der's bis hierher geschafft hat, Kumpel. Schade nur, dass du gleich wieder raus auf die Aasfelder musst. Ja, genau - wir hatten so was wie 'nen kleinen Rückschlag.", sourceObjectiveStatus = "unverified-source-field" }
quests[12327] = { id = 12327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außerkörperliche Erfahrung", description = "Ah, Ihr sucht nach einer Vision der Vergangenheit. Ihr seid <ein weiser/eine weise:r> {race}.\n\nJedes Mal, wenn jemand hierher kommt und etwas wissen möchte, dann wollen sie anscheinend immer nur die Zukunft erfahren. Wenn Ihr mein Alter erreicht, dann erkennt Ihr, dass es in den meisten Fällen einfach nützlicher ist, in die Vergangenheit zu blicken.\n\nTrinkt von diesem Trank und werft einen Blick in meine Kristallkugel. Lasst uns sehen, was wir herausbekommen können.", sourceObjective = "Trinkt den samtigen Trank bei Ruunas Kristallkugel und werdet Zeuge einer Vision der Vergangenheit.", progress = "Ja, {name}?", completion = "Habt Ihr irgendetwas aus Eurer Vision erfahren können? Ihr habt Julheim erwähnt, während Ihr Euch in Trance befandet - was das zweite Mal ist, dass heute jemand den Namen dieses Ortes ausspricht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12328] = { id = 12328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruunas Bitte", description = "Ich werde Euch für meine Dienste kein Gold abnehmen, weil ich ahne, dass Eure Taten notwendig sind und viel davon abhängt, was Ihr heute lernt.\n\nIch werde Euch jedoch darum bitten, ein Reagenz für mich zu besorgen. Bringt mir samtigen Staub von den Farnfressermotten nordöstlich von hier. Tut das und ich werde Euch einen Trank bereiten, der Euch an den Ort und die Zeit bringt, da die Geschehnisse stattfanden, die Ihr gesehen haben müsst.", sourceObjective = "Ruuna die Blinde möchte, dass Ihr 4 Handvoll samtigen Staubs besorgt.", progress = "Habt Ihr den Staub bekommen, {name}?", completion = "Gut. Das wird ausreichen.\n\nIm Handumdrehen werde ich den Trank fertig haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12329] = { id = 12329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal und Zufall", description = "Es gibt zwei Arten von Leuten auf dieser Welt, {name}. Diejenigen, die an den Zufall glauben, und diejenigen, die nicht daran glauben.\n\nAn dem Tag, als ich mein Augenlicht verlor, wurde mir das Geschenk des Hellsehens zuteil. Ich nehme an, dass Ihr erraten könnt, zu welcher Gruppe von Leuten ich gehöre.\n\nHeute früh wurde einer jungen Frau namens Sasha dieselbe Vision gewährt wie Euch. Ihr werdet mit ihr sprechen wollen.\n\nIhr findet sie direkt östlich von hier im Handelsposten Weißkiefer auf dem Weg nach Julheim.", sourceObjective = "Sprecht mit Sasha im Handelsposten Weißkiefer.", completion = "Ich habe mich schon gefragt, wann Ihr auftauchen würdet. Denkt Ihr, dass Ihr mir hier helfen könntet?", sourceObjectiveStatus = "unverified-source-field" }
quests[12330] = { id = 12330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anatol wird reden", description = "Meine Schwester ist hier irgendwo, und ich kriege dieses Monster einfach nicht zum Reden.\n\nEr kümmert sich anscheinend nicht um sein eigenes Wohlergehen, aber ich habe da eine Idee. Ich kenne Anatols Frau, Tatjana, noch aus der Zeit, bevor der Wolfkult ankam; sie war eine Pferdeausbilderin.\n\nNehmt diesen Betäubungspfeil. Bringt sie lebend zurück, wir werden sie brauchen, wenn wir ein Druckmittel gegen Anatol haben wollen.\n\nIch werde Euch helfen, die Person zu finden, die hinter all dem steckt, sobald wir meine Schwester haben.", sourceObjective = "Sasha im Handelsposten Weißkiefer möchte, dass Ihr den Betäubungspfeil nehmt und ihn auf Tatjana in Julheim schießt. Bringt Tatjana dann zum Handelsposten Weißkiefer zurück.", completion = "Das… das war knapp.\n\nWir müssen Anya retten. Jetzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12331] = { id = 12331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
