quests[12372] = { id = 12372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt den Wyrmruhtempel", description = "Der blaue Drachenschwarm ist vom Überfluss an Magie, die nun durch den Azurdrachenschrein fließt, ermutigt und hat es gewagt, den Wyrmruhtempel selbst anzugreifen!\n\nIch möchte, dass Ihr mit einem unserer Verteidiger in die Schlacht fliegt, ihre Großdrachen und Drachen niederstreckt und die Eruptionen der Leylinienenergien im Drachenschrein unter Beschuss nehmt, um ihn zu destabilisieren.\n\nSprecht mit einem der Verteidiger des Wyrmruhtempels, die sich auf der Ost- und Westterrasse befinden, und fliegt mit ihm in die Schlacht.\n\nOhne Eure Hilfe, {name}, wird unsere Niederlage unausweichlich sein.", sourceObjective = "Devrestrasz im Wyrmruhtempel möchte, dass Ihr auf dem Rücken eines Verteidigers des Wyrmruhtempels in die Schlacht reitet, 3 Azurgroßdrachen und 5 Azurdrachen tötet und den Azurdrachenschrein destabilisiert.", completion = "Unglaublich! Lasst mich nur sagen, dass ich weiterhin erstaunt bin, zu welchen Leistungen die jüngeren Völker anscheinend fähig sind.\n\nWir stehen in Eurer Schuld. Werdet Ihr morgen wieder zurückkommen und uns einmal mehr zur Seite stehen?", sourceObjectiveStatus = "unverified-source-field" }
